PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?riskPressureScore WHERE {
  ?inv a wm:Investor .
  ?inv wm:investorId ?investorId .
  ?inv wm:investorName ?investorName .

  {
    SELECT ?investorId (MAX(xsd:decimal(?riskScoreRaw)) AS ?riskScore) (MAX(xsd:decimal(?liqScoreRaw)) AS ?liquidityScore)
    WHERE {
      ?ph a wm:PortfolioHealth .
      ?ph wm:investorId ?investorId .
      ?ph wm:riskScore ?riskScoreRaw .
      ?ph wm:liquidityScore ?liqScoreRaw .
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (AVG(xsd:decimal(?allocPctRaw)) AS ?allocationConcentration)
    WHERE {
      ?sa a wm:SectorAllocation .
      ?sa wm:investorId ?investorId .
      ?sa wm:allocationPct ?allocPctRaw .
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (AVG(xsd:decimal(?volRaw)) AS ?goalVolatility)
    WHERE {
      ?goal a wm:InvestmentGoal .
      ?goal wm:investorId ?investorId .
      ?goal wm:avgVolatilityPct ?volRaw .
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (AVG(xsd:decimal(?currAllocRaw)) AS ?currentAllocationPct) (AVG(xsd:decimal(?newAllocRaw)) AS ?newAllocationPct) (AVG(xsd:decimal(?newAllocRaw)) - AVG(xsd:decimal(?currAllocRaw)) AS ?scenarioChange)
    WHERE {
      ?sr a wm:ScenarioRebalancing .
      ?sr wm:investorId ?investorId .
      ?sr wm:currentAllocationPct ?currAllocRaw .
      ?sr wm:newAllocationPct ?newAllocRaw .
    } GROUP BY ?investorId
  }

  BIND((?riskScore + ?allocationConcentration + ?goalVolatility - ?liquidityScore + ?scenarioChange) AS ?riskPressureScore)
}
ORDER BY DESC(?riskPressureScore) ?investorId
LIMIT 10

