PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment
       (AVG(?scenarioChange) AS ?avg_scenario_change)
       (AVG(?goalProgress) AS ?avg_goal_progress)
       (AVG(?volatility) AS ?avg_volatility)
WHERE {
  # Segment per investor from holdings
  {
    SELECT DISTINCT ?investorId ?segment
    WHERE {
      ?holding a wm:PortfolioHolding .
      ?holding wm:investorId ?investorId .
      OPTIONAL { ?holding wm:segment ?segmentRaw . }
      BIND(COALESCE(STR(?segmentRaw), "NULL") AS ?segment)
    }
  }

  # Average scenario change per investor
  {
    SELECT ?investorId (AVG(xsd:decimal(?diff)) AS ?scenarioChange)
    WHERE {
      ?rebalance a wm:ScenarioRebalancing .
      ?rebalance wm:investorId ?investorId .
      ?rebalance wm:newAllocationPct ?newAlloc .
      ?rebalance wm:currentAllocationPct ?currAlloc .
      BIND(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc) AS ?diff)
    }
    GROUP BY ?investorId
  }

  # Average goal progress and volatility per investor
  {
    SELECT ?investorId (AVG(xsd:decimal(?progress)) AS ?goalProgress) (AVG(xsd:decimal(?vol)) AS ?volatility)
    WHERE {
      ?goal a wm:InvestmentGoal .
      ?goal wm:investorId ?investorId .
      ?goal wm:progressPct ?progress .
      ?goal wm:avgVolatilityPct ?vol .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?segment

