SELECT ?riskTolerance
       (AVG(xsd:decimal(?rebalanceSum)) AS ?avg_rebalancing_amount)
       (AVG(xsd:decimal(?cashFlowSum)) AS ?avg_cash_flow_amount)
       (AVG(xsd:decimal(?goalProgressAvg)) AS ?avg_goal_progress)
       (AVG(xsd:decimal(?shortfallAvg)) AS ?avg_shortfall)
WHERE {
  # Investor base
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:riskTolerance ?riskTolerance .

  # Pre‑aggregate RebalancingAction per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?raAmount)) AS ?rebalanceSum)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:investorId ?investorId ;
          wm:amount ?raAmount .
    }
    GROUP BY ?investorId
  }

  # Pre‑aggregate CashFlow per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?cashFlowSum)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?cfAmount .
    }
    GROUP BY ?investorId
  }

  # Pre‑aggregate InvestmentGoal per investor (average progress and shortfall)
  {
    SELECT ?investorId (AVG(xsd:decimal(?progress)) AS ?goalProgressAvg)
                     (AVG(xsd:decimal(?shortfall)) AS ?shortfallAvg)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:progressPct ?progress ;
            wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?riskTolerance

