PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?time_horizon
       (AVG(?shortfall) AS ?avg_shortfall)
       (AVG(?holdingValue) AS ?total_holding_value)
       (AVG(?allocPct) AS ?avg_allocation_pct)
       (AVG(?liqScore) AS ?avg_liquidity_score)
       (AVG(?divScore) AS ?avg_diversification_score)
WHERE {
  # Investor and its time horizon
  ?inv a wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:timeHorizon ?time_horizon_raw . }
  BIND(COALESCE(STR(?time_horizon_raw), "NULL") AS ?time_horizon)

  # Shortfall per investor
  {
    SELECT ?investorId (AVG(xsd:decimal(?sf)) AS ?shortfall)
    WHERE {
      ?goal a wm:InvestmentGoal .
      ?goal wm:investorId ?investorId .
      ?goal wm:shortfall ?sf .
    }
    GROUP BY ?investorId
  }

  # Holding value per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?cv)) AS ?holdingValue)
    WHERE {
      ?hold a wm:PortfolioHolding .
      ?hold wm:investorId ?investorId .
      ?hold wm:currentValue ?cv .
    }
    GROUP BY ?investorId
  }

  # Allocation pct per investor
  {
    SELECT ?investorId (AVG(xsd:decimal(?ap)) AS ?allocPct)
    WHERE {
      ?alloc a wm:SectorAllocation .
      ?alloc wm:investorId ?investorId .
      ?alloc wm:allocationPct ?ap .
    }
    GROUP BY ?investorId
  }

  # Liquidity score per investor
  {
    SELECT ?investorId (AVG(xsd:decimal(?ls)) AS ?liqScore)
    WHERE {
      ?ph a wm:PortfolioHealth .
      ?ph wm:investorId ?investorId .
      ?ph wm:liquidityScore ?ls .
    }
    GROUP BY ?investorId
  }

  # Diversification score per investor
  {
    SELECT ?investorId (AVG(xsd:decimal(?ds)) AS ?divScore)
    WHERE {
      ?ph2 a wm:PortfolioHealth .
      ?ph2 wm:investorId ?investorId .
      ?ph2 wm:diversificationScore ?ds .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?time_horizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?rebalance_logic ?avg_scenario_change
WHERE {
  {
    SELECT ?logic (AVG(?avgChangePerInvestor) AS ?avg_scenario_change)
    WHERE {
      {
        SELECT ?investorId (AVG(xsd:decimal(?change)) AS ?avgChangePerInvestor)
        WHERE {
          ?sr a wm:ScenarioRebalancing .
          ?sr wm:investorId ?investorId .
          ?sr wm:newAllocationPct ?newPct .
          ?sr wm:currentAllocationPct ?curPct .
          BIND( (xsd:decimal(?newPct) - xsd:decimal(?curPct)) AS ?change )
        }
        GROUP BY ?investorId
      }
      ?ra a wm:RebalancingAction .
      ?ra wm:investorId ?investorId .
      ?ra wm:logic ?logic .
    }
    GROUP BY ?logic
  }
  BIND(?logic AS ?rebalance_logic)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?time_horizon
       (AVG(?goalProgressAvg) AS ?avg_goal_progress)
       (AVG(?riskScoreAvg) AS ?avg_health_risk)
       (AVG(?liquidityAvg) AS ?avg_liquidity)
WHERE {
  # cash‑flow dates per investor (time horizon)
  {
    SELECT DISTINCT ?date ?investorId
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:date ?date .
    }
  }
  BIND(?date AS ?time_horizon)

  # goal progress aggregated per investor
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?goalProgressAvg)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
  }

  # health risk and liquidity aggregated per investor
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?riskScore)) AS ?riskScoreAvg)
           (AVG(xsd:decimal(?liquidityScore)) AS ?liquidityAvg)
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:investorId ?investorId ;
          wm:riskScore ?riskScore ;
          wm:liquidityScore ?liquidityScore .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?time_horizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?goal_match_pct_band
       (AVG(xsd:decimal(?riskScore)) AS ?avg_risk_score)
       (AVG(xsd:decimal(?liquidityScore)) AS ?avg_liquidity_score)
       (AVG(xsd:decimal(?diversificationScore)) AS ?avg_diversification_score)
WHERE {
  ?ph a wm:PortfolioHealth .
  OPTIONAL { ?ph wm:goalMatchPct ?goalMatchPct . }
  BIND(COALESCE(STR(?goalMatchPct), "NULL") AS ?goal_match_pct_band)
  OPTIONAL { ?ph wm:riskScore ?riskScore . }
  OPTIONAL { ?ph wm:liquidityScore ?liquidityScore . }
  OPTIONAL { ?ph wm:diversificationScore ?diversificationScore . }
}
GROUP BY ?goal_match_pct_band

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?time_horizon
       (AVG(?avgGoalProgress) AS ?avg_goal_progress)
       (AVG(?totalHoldingGain) AS ?avg_holding_gain)
       (AVG(?avgRiskScore) AS ?avg_risk_score)
       (AVG(?avgLiquidityScore) AS ?avg_liquidity_score)
WHERE {
  {
    SELECT ?investorId ?time_horizon
           (AVG(xsd:decimal(?progressPct)) AS ?avgGoalProgress)
           (SUM(xsd:decimal(?currVal) - xsd:decimal(?cost)) AS ?totalHoldingGain)
           (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
           (AVG(xsd:decimal(?liquidityScore)) AS ?avgLiquidityScore)
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?investorId ;
           wm:timeHorizon ?time_horizon .

      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv ;
            wm:progressPct ?progressPct .

      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?inv ;
               wm:currentValue ?currVal ;
               wm:cost ?cost .

      ?ph a wm:PortfolioHealth ;
          wm:healthOfInvestor ?inv ;
          wm:riskScore ?riskScore ;
          wm:liquidityScore ?liquidityScore .
    }
    GROUP BY ?investorId ?time_horizon
  }
}
GROUP BY ?time_horizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?type (SUM(xsd:decimal(?inv_type_amount)) AS ?total_amount)
WHERE {
  {
    SELECT ?invId ?type (SUM(xsd:decimal(?amount)) AS ?inv_type_amount)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:investorId ?invId ;
                wm:amount ?amount ;
                wm:type ?type .
      FILTER ( LCASE(STR(?type)) = "deposit" || LCASE(STR(?type)) = "withdrawal" )
    }
    GROUP BY ?invId ?type
  }
  ?investor a wm:Investor ;
            wm:investorId ?invId .
  OPTIONAL { ?investor wm:riskTolerance ?rt . }
  BIND(COALESCE(STR(?rt), "NULL") AS ?riskTolerance)
}
GROUP BY ?riskTolerance ?type

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  ?investor wm:investorName ?investorName .

  FILTER EXISTS {
    ?investor wm:hasInvestmentGoal ?goal .
    ?goal wm:investmentGoal ?goalType .
    FILTER(LCASE(STR(?goalType)) = "growth")
  }

  FILTER EXISTS {
    ?investor wm:hasHolding ?holding .
    ?holding wm:sector ?holdingSector .
    FILTER(LCASE(STR(?holdingSector)) = "technology")
  }

  FILTER EXISTS {
    ?investor wm:hasSectorAllocation ?alloc .
    ?alloc wm:sector ?allocSector .
    FILTER(LCASE(STR(?allocSector)) = "technology")
  }

  FILTER EXISTS {
    ?investor wm:hasCashFlow ?cf .
    ?cf wm:type ?cfType .
    FILTER(LCASE(STR(?cfType)) = "sip")
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment
       (AVG(?cashFlowSum) AS ?avg_cash_flow_net_amount)
       (AVG(?goalProgressAvg) AS ?avg_goal_progress_pct)
       (AVG(?shortfallAvg) AS ?avg_shortfall)
WHERE {
  ?investor a wm:Investor .
  OPTIONAL { ?investor wm:segment ?segmentRaw . }
  BIND(COALESCE(?segmentRaw, "NULL") AS ?segment)

  {
    SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?cashFlowSum)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:amount ?amount ;
                wm:cashFlowOfInvestor ?investor .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor
           (AVG(xsd:decimal(?progressPct)) AS ?goalProgressAvg)
           (AVG(xsd:decimal(?shortfall)) AS ?shortfallAvg)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPct ;
            wm:shortfall ?shortfall .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?segment

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category (SUM(?invDiv) AS ?total_dividends) (SUM(?invTax) AS ?total_taxes_paid)
WHERE {
  {
    SELECT ?investor (SUM(?divVal) AS ?invDiv) (SUM(?taxVal) AS ?invTax)
    WHERE {
      ?holding a wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      OPTIONAL { ?holding wm:dividends ?divRaw . }
      OPTIONAL { ?holding wm:taxesPaid ?taxRaw . }
      BIND(COALESCE(xsd:decimal(?divRaw), 0) AS ?divVal) .
      BIND(COALESCE(xsd:decimal(?taxRaw), 0) AS ?taxVal) .
    }
    GROUP BY ?investor
  }
  ?investor a wm:Investor .
  OPTIONAL { ?investor wm:category ?catRaw . }
  BIND(COALESCE(STR(?catRaw), "NULL") AS ?category) .
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (AVG(xsd:decimal(?allocSum)) AS ?allocation_concentration)
       (AVG(xsd:decimal(?holdReturnAvg)) AS ?holding_return)
       (SUM(xsd:decimal(?holdValueSum)) AS ?holding_value)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?allocationPct)) AS ?allocSum)
    WHERE {
      ?sa a wm:SectorAllocation .
      ?sa wm:investorId ?investorId .
      ?sa wm:allocationPct ?allocationPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId ?category
           (AVG(xsd:decimal(?returnsPct)) AS ?holdReturnAvg)
           (SUM(xsd:decimal(?currentValue)) AS ?holdValueSum)
    WHERE {
      ?ph a wm:PortfolioHolding .
      ?ph wm:investorId ?investorId .
      ?ph wm:category ?category .
      ?ph wm:returnsPct ?returnsPct .
      ?ph wm:currentValue ?currentValue .
    }
    GROUP BY ?investorId ?category
  }
  FILTER EXISTS {
    ?phCheck a wm:PortfolioHolding ;
             wm:investorId ?investorId ;
             wm:category ?category .
  }
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }
  OPTIONAL { ?inv wm:riskTolerance ?rt . }
  OPTIONAL { ?inv wm:category ?cat . }
  FILTER ( (!BOUND(?rt) || STRLEN(STR(?rt)) = 0) && (!BOUND(?cat) || STRLEN(STR(?cat)) = 0) )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?avg_volatility_pct ?avg_sharpe_ratio ?risk_score
WHERE {
  # Anchor investor to retrieve name
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  # Aggregate InvestmentGoal metrics per investor
  {
    SELECT ?investorId (AVG(xsd:decimal(?vol)) AS ?avg_volatility_pct) (AVG(xsd:decimal(?sharpe)) AS ?avg_sharpe_ratio)
    WHERE {
      ?invGoal a wm:Investor ;
               wm:investorId ?investorId ;
               wm:hasInvestmentGoal ?goal .
      ?goal wm:avgVolatilityPct ?vol ;
            wm:avgSharpeRatio ?sharpe .
    }
    GROUP BY ?investorId
  }

  # Aggregate PortfolioHealth riskScore per investor
  {
    SELECT ?investorId (AVG(xsd:decimal(?risk)) AS ?risk_score)
    WHERE {
      ?invHealth a wm:Investor ;
                 wm:investorId ?investorId ;
                 wm:hasPortfolioHealth ?ph .
      ?ph wm:riskScore ?risk .
    }
    GROUP BY ?investorId
  }

  FILTER(?avg_volatility_pct > 20 && ?avg_sharpe_ratio < 0 && ?risk_score > 50)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?holdingCount ?cashFlowCount ?rebalancingCount ?scenarioRebalancingCount
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }

  FILTER NOT EXISTS {
    ?goal a wm:InvestmentGoal ;
          wm:investorId ?investorId .
  }

  {
    SELECT ?investorId (COUNT(?holdingId) AS ?holdingCount)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:holdingId ?holdingId .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (COUNT(?cashFlowId) AS ?cashFlowCount)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:cashFlowId ?cashFlowId .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (COUNT(?rebalanceId) AS ?rebalancingCount)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:investorId ?investorId ;
          wm:rebalanceId ?rebalanceId .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (COUNT(?scenarioRebalanceId) AS ?scenarioRebalancingCount)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?investorId ;
          wm:scenarioRebalanceId ?scenarioRebalanceId .
    }
    GROUP BY ?investorId
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  # Investor basic info
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  # Portfolio health with liquidity filter
  ?ph a wm:PortfolioHealth ;
       wm:investorId ?investorId ;
       wm:liquidityScore ?liquidityScore .
  FILTER (xsd:decimal(?liquidityScore) < 30)

  # Aggregate holding gain per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?totalHoldingGain)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:currentValue ?curr ;
               wm:cost ?cost .
      BIND (xsd:decimal(?curr) - xsd:decimal(?cost) AS ?gain)
    }
    GROUP BY ?investorId
  }
  FILTER (xsd:decimal(?totalHoldingGain) < 0)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category ?cashFlowType (COUNT(DISTINCT ?investorId) AS ?investorCount)
WHERE {
  {
    SELECT DISTINCT ?investorId ?category ?cashFlowType WHERE {
      ?inv rdf:type wm:Investor .
      ?inv wm:investorId ?investorId .
      OPTIONAL { ?inv wm:category ?catRaw . }
      BIND(COALESCE(?catRaw, "NULL") AS ?category) .
      ?inv wm:hasCashFlow ?cf .
      ?cf rdf:type wm:CashFlow .
      OPTIONAL { ?cf wm:type ?cfTypeRaw . }
      BIND(COALESCE(?cfTypeRaw, "NULL") AS ?cashFlowType) .
      ?inv wm:hasRebalancingAction ?ra .
      ?ra rdf:type wm:RebalancingAction .
    }
  }
}
GROUP BY ?category ?cashFlowType

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (SUM(xsd:decimal(?holdingSum0)) AS ?total_holding_purchases)
       (SUM(xsd:decimal(?cashFlowSum0)) AS ?total_cash_flow)
WHERE {
  ?investor a wm:Investor .
  OPTIONAL { ?investor wm:riskTolerance ?rt . }
  BIND(COALESCE(?rt, "NULL") AS ?riskTolerance)

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?cost)) AS ?holdingSum)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:cost ?cost ;
               wm:purchaseDate ?pdate .
      FILTER(CONTAINS(LCASE(STR(?pdate)), "2024"))
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?cashFlowSum)
    WHERE {
      ?cashFlow a wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount ;
                wm:date ?cdate .
      FILTER(CONTAINS(LCASE(STR(?cdate)), "2024"))
    }
    GROUP BY ?investor
  }

  BIND(COALESCE(?holdingSum, "0"^^xsd:decimal) AS ?holdingSum0)
  BIND(COALESCE(?cashFlowSum, "0"^^xsd:decimal) AS ?cashFlowSum0)
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (SUM(?raSum) AS ?total_rebalancing_amount)
       (SUM(?cfSum) AS ?total_cash_flow_amount)
       (SUM(?raCount) AS ?transaction_count)
WHERE {
  # Investor with its category
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:category ?category .

  # Pre‑aggregate RebalancingAction per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?raAmount)) AS ?raSum) (COUNT(?rebalanceId) AS ?raCount)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:investorId ?investorId ;
          wm:amount ?raAmount ;
          wm:rebalanceId ?rebalanceId .
    }
    GROUP BY ?investorId
  }

  # Pre‑aggregate CashFlow per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?cfSum)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?cfAmount .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?category

