SELECT ?category
       (AVG(?avgCostInv) AS ?avg_allocation_pct)
       (AVG(?avgReturnInv) AS ?avg_holding_returns)
WHERE {
  {
    SELECT ?investor (AVG(xsd:decimal(?cost)) AS ?avgCostInv) (AVG(xsd:decimal(?returnsPct)) AS ?avgReturnInv)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:cost ?cost ;
               wm:returnsPct ?returnsPct .
    }
    GROUP BY ?investor
  }
  ?investor a wm:Investor .
  OPTIONAL { ?investor wm:category ?catRaw . }
  BIND(COALESCE(STR(?catRaw), "NULL") AS ?category)
}
