PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?logic ?action WHERE {
  ?ra a wm:RebalancingAction ;
      wm:rebalanceId "0000aba5-8fe8-4dcf-b422-fd78608ffddb" ;
      wm:logic ?logic ;
      wm:action ?action .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?profile_category
       (AVG(?goalShortfall) AS ?avg_goal_shortfall)
       (AVG(?allocPct) AS ?avg_allocation_concentration)
       (AVG(?liqScore) AS ?avg_health_liquidity)
       (AVG(?divScore) AS ?avg_diversification)
WHERE {
  # Ensure the investor exists
  ?inv a wm:Investor ;
       wm:investorId ?investorId .

  # InvestmentGoal per‑investor aggregation (provides shortfall and profile category)
  {
    SELECT ?investorId ?sourceTable (AVG(xsd:decimal(?shortfall)) AS ?goalShortfall)
    WHERE {
      ?ig a wm:InvestmentGoal ;
          wm:investorId ?investorId ;
          wm:shortfall ?shortfall ;
          wm:sourceTable ?sourceTable .
    }
    GROUP BY ?investorId ?sourceTable
  }

  # SectorAllocation per‑investor aggregation (allocation concentration)
  {
    SELECT ?investorId (AVG(xsd:decimal(?allocationPct)) AS ?allocPct)
    WHERE {
      ?sa a wm:SectorAllocation ;
          wm:investorId ?investorId ;
          wm:allocationPct ?allocationPct .
    }
    GROUP BY ?investorId
  }

  # PortfolioHealth per‑investor aggregation (liquidity and diversification)
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?liquidityScore)) AS ?liqScore)
           (AVG(xsd:decimal(?diversificationScore)) AS ?divScore)
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:investorId ?investorId ;
          wm:liquidityScore ?liquidityScore ;
          wm:diversificationScore ?diversificationScore .
    }
    GROUP BY ?investorId
  }

  # RebalancingAction existence per‑investor
  {
    SELECT DISTINCT ?investorId
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:investorId ?investorId .
    }
  }

  BIND(?sourceTable AS ?profile_category)
}
GROUP BY ?profile_category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avgProgress)
    WHERE {
      ?goal a wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?inv .
      ?inv wm:investorId ?investorId .
      ?goal wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
    HAVING (AVG(xsd:decimal(?progressPct)) < 25)
  }
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .
  ?alloc a wm:SectorAllocation ;
         wm:allocationOfInvestor ?inv ;
         wm:allocationPct ?allocPct .
  FILTER (xsd:decimal(?allocPct) > 40)
  ?ph a wm:PortfolioHealth ;
      wm:healthOfInvestor ?inv ;
      wm:diversificationScore ?divScore .
  FILTER (xsd:decimal(?divScore) < 30)
}
GROUP BY ?investorId ?investorName

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  ?cf a wm:CashFlow ;
      wm:cashFlowOfInvestor ?inv ;
      wm:type ?cfType .
  FILTER(LCASE(STR(?cfType)) = "deposit") .

  ?ra a wm:RebalancingAction ;
      wm:rebalancingActionOfInvestor ?inv .

  ?sr a wm:ScenarioRebalancing ;
      wm:scenarioRebalancingOfInvestor ?inv ;
      wm:scenario ?srScenario .
  FILTER(LCASE(STR(?srScenario)) = "economic growth") .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName ?avg_progress_pct ?avg_sharpe_ratio ?risk_score
WHERE {
  ?inv a wm:Investor ;
       wm:investorName ?investorName .

  ?ph a wm:PortfolioHealth ;
      wm:healthOfInvestor ?inv ;
      wm:riskScore ?risk_score .

  {
    SELECT ?inv (AVG(xsd:decimal(?progressPct)) AS ?avg_progress_pct) (AVG(xsd:decimal(?sharpeRatio)) AS ?avg_sharpe_ratio)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv ;
            wm:progressPct ?progressPct ;
            wm:avgSharpeRatio ?sharpeRatio .
    }
    GROUP BY ?inv
  }

  FILTER ( ?avg_progress_pct < 40 && ?avg_sharpe_ratio < 0 && xsd:decimal(?risk_score) > 70 )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasPortfolioHealth ?ph .
  ?ph wm:riskPressureScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 180)

  {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?avgProgress)
    WHERE {
      ?investor wm:hasInvestmentGoal ?goal .
      ?goal wm:progressPct ?progressPct .
    }
    GROUP BY ?investor
    HAVING (AVG(xsd:decimal(?progressPct)) < 40)
  }

  {
    SELECT ?investor (SUM(xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?totalGain)
    WHERE {
      ?investor wm:hasHolding ?holding .
      ?holding wm:currentValue ?currentValue ;
               wm:cost ?cost .
    }
    GROUP BY ?investor
    HAVING (SUM(xsd:decimal(?currentValue) - xsd:decimal(?cost)) < 0)
  }

  {
    SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?netCash)
    WHERE {
      ?investor wm:hasCashFlow ?cashFlow .
      ?cashFlow wm:amount ?amount .
    }
    GROUP BY ?investor
    HAVING (SUM(xsd:decimal(?amount)) < 0)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
