SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:riskTolerance ?riskTolerance ;
            wm:investmentGoal ?investmentGoal .
  FILTER( STR(?investorId) != "" && STR(?investorName) != "" && STR(?riskTolerance) != "" && STR(?investmentGoal) != "" )

  FILTER EXISTS {
    ?investor wm:hasHolding ?holding .
    ?holding rdf:type wm:PortfolioHolding .
    FILTER NOT EXISTS {
      ?holding wm:category ?cat .
      FILTER( STR(?cat) != "" )
    }
  }
}
