SELECT ?month (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
WHERE {
  ?cashFlow rdf:type wm:CashFlow ;
            wm:amount ?amount ;
            wm:date ?date ;
            wm:cashFlowOfInvestor ?investor .

  ?investor rdf:type wm:Investor ;
            wm:hasPortfolioHealth ?ph .

  ?ph rdf:type wm:PortfolioHealth ;
      wm:riskScore ?riskScore .

  FILTER(xsd:decimal(?riskScore) > 70)

  BIND(SUBSTR(STR(?date), 1, 7) AS ?month)
  FILTER(STRSTARTS(?month, "2025-"))
}
GROUP BY ?month
ORDER BY ?month

