    SELECT ?investorId (SUM(xsd:decimal(?dividend)) AS ?totalDividends)
    WHERE {
      ?holding a wm:PortfolioHolding .
      ?holding wm:dividends ?dividend .
      ?holding wm:investorId ?investorId .
    }
