PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment (COALESCE(?invCount, 0) AS ?profileSegmentCount) (COALESCE(?holdCount, 0) AS ?holdingSegmentCount)
WHERE {
  # Gather all segment values appearing in either Investors or Holdings
  {
    SELECT DISTINCT ?segment WHERE {
      { ?inv a wm:Investor ; wm:segment ?segment . }
      UNION
      { ?hold a wm:PortfolioHolding ; wm:segment ?segment . }
    }
  }
  # Count Investors per segment
  OPTIONAL {
    SELECT ?segment (COUNT(?inv) AS ?invCount) WHERE {
      ?inv a wm:Investor ; wm:segment ?segment .
    } GROUP BY ?segment
  }
  # Count Holdings per segment
  OPTIONAL {
    SELECT ?segment (COUNT(?hold) AS ?holdCount) WHERE {
      ?hold a wm:PortfolioHolding ; wm:segment ?segment .
    } GROUP BY ?segment
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category ?cash_flow_source (SUM(xsd:decimal(?amount)) AS ?total_amount)
WHERE {
  ?cf a wm:CashFlow .

  OPTIONAL { ?cf wm:type ?cat . }
  BIND(COALESCE(STR(?cat), "NULL") AS ?category) .

  OPTIONAL {
    ?cf wm:hasCashFlowSource ?src .
    OPTIONAL { ?src rdfs:label ?srcLabel . }
    BIND(COALESCE(STR(?srcLabel), STR(?src), "NULL") AS ?cash_flow_source) .
  }

  ?cf wm:amount ?amount .
}
GROUP BY ?category ?cash_flow_source

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName WHERE {
  ?investor a wm:Investor .
  ?investor wm:investorId ?investorId .
  ?investor wm:investorName ?investorName .

  FILTER EXISTS {
    ?investor wm:hasInvestmentGoal ?goal .
    ?goal wm:shortfall ?shortfall .
    FILTER(xsd:decimal(?shortfall) > 0)
  }

  FILTER EXISTS {
    ?investor wm:hasHolding ?holding .
    ?holding wm:returnsPct ?returns .
    FILTER(xsd:decimal(?returns) < 0)
  }

  FILTER EXISTS {
    ?investor wm:hasSectorAllocation ?alloc .
    ?alloc wm:allocationPct ?allocPct .
    FILTER(xsd:decimal(?allocPct) > 25)
  }

  FILTER EXISTS {
    ?investor wm:hasPortfolioHealth ?health .
    ?health wm:diversificationScore ?divScore .
    FILTER(xsd:decimal(?divScore) < 40)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT 
  (COUNT(DISTINCT ?invWith) AS ?investorsWithHoldingSegment)
  (COUNT(DISTINCT ?invWithout) AS ?investorsWithoutHoldingSegment)
WHERE {
  {
    SELECT DISTINCT ?invWith WHERE {
      ?invWith a wm:Investor ;
               wm:hasSegment ?seg .
      ?hold a wm:PortfolioHolding ;
            wm:heldByInvestor ?invWith ;
            wm:hasSegment ?seg .
    }
  }
  UNION
  {
    SELECT DISTINCT ?invWithout WHERE {
      ?invWithout a wm:Investor .
      FILTER NOT EXISTS {
        ?invWithout wm:hasSegment ?seg .
        ?hold a wm:PortfolioHolding ;
              wm:heldByInvestor ?invWithout ;
              wm:hasSegment ?seg .
      }
    }
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?score WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  {
    SELECT ?investorId (SUM(xsd:decimal(?shortfall)) AS ?total_shortfall) WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:shortfall ?shortfall ;
            wm:belongsToInvestor ?invGoal .
      ?invGoal wm:investorId ?investorId .
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?total_holding_gain) WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:currentValue ?cv ;
               wm:cost ?cost ;
               wm:heldByInvestor ?invHolding .
      BIND (xsd:decimal(?cv) - xsd:decimal(?cost) AS ?gain) .
      ?invHolding wm:investorId ?investorId .
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?net_cash_flow) WHERE {
      ?cf a wm:CashFlow ;
          wm:amount ?amount ;
          wm:cashFlowOfInvestor ?invCf .
      ?invCf wm:investorId ?investorId .
    } GROUP BY ?investorId
  }

  BIND ( ?total_shortfall - ?total_holding_gain - ?net_cash_flow AS ?score ) .
  FILTER ( xsd:decimal(?score) > 50000000 )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorName ?temporalPressureScore WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  ?inv wm:investorName ?investorName .

  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?cashFlow2025) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:investorId ?investorId .
      ?cf wm:amount ?cfAmount .
      ?cf wm:date ?cfDate .
      FILTER(CONTAINS(STR(?cfDate), "2025"))
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?rebAmount)) AS ?rebalanceAmount) WHERE {
      ?ra rdf:type wm:RebalancingAction .
      ?ra wm:investorId ?investorId .
      ?ra wm:amount ?rebAmount .
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?shortfall)) AS ?totalShortfall) WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:investorId ?investorId .
      ?goal wm:shortfall ?shortfall .
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?allocationChange) WHERE {
      ?scen rdf:type wm:ScenarioRebalancing .
      ?scen wm:investorId ?investorId .
      ?scen wm:newAllocationPct ?newAlloc .
      ?scen wm:currentAllocationPct ?currAlloc .
    } GROUP BY ?investorId
  }

  BIND( (xsd:decimal(?cashFlow2025) + xsd:decimal(?rebalanceAmount) - xsd:decimal(?totalShortfall) + xsd:decimal(?allocationChange)) AS ?temporalPressureScore )
}
ORDER BY DESC(?temporalPressureScore) ?investorName
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment
       (AVG(?totalGain) AS ?avg_holding_gain)
       (AVG(?riskScore) AS ?avg_risk_score)
       (AVG(?divScore) AS ?avg_diversification_score)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?totalGain)
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?investorId .
      ?holding a wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:currentValue ?curr ;
               wm:cost ?cost .
      BIND( (xsd:decimal(?curr) - xsd:decimal(?cost)) AS ?gain )
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?riskScoreRaw)) AS ?riskScore) (AVG(xsd:decimal(?divScoreRaw)) AS ?divScore)
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?investorId .
      ?health a wm:PortfolioHealth ;
               wm:investorId ?investorId ;
               wm:riskScore ?riskScoreRaw ;
               wm:diversificationScore ?divScoreRaw .
    }
    GROUP BY ?investorId
  }
  {
    SELECT DISTINCT ?investorId ?segment
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?investorId .
      ?h a wm:PortfolioHolding ;
         wm:investorId ?investorId .
      OPTIONAL { ?h wm:segment ?segmentRaw . }
      BIND(COALESCE(STR(?segmentRaw), "NULL") AS ?segment)
    }
  }
}
GROUP BY ?segment

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?netCashFlow ?avgGoalProgress ?riskScore ?scenarioChange
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .

  {
    SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
    WHERE {
      ?cash a wm:CashFlow ;
            wm:cashFlowOfInvestor ?investor ;
            wm:amount ?amount .
    }
    GROUP BY ?investor
    HAVING (SUM(xsd:decimal(?amount)) > 100000000)
  }

  {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?avgGoalProgress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?investor
    HAVING (AVG(xsd:decimal(?progressPct)) < 25)
  }

  {
    SELECT ?investor (MAX(xsd:decimal(?riskScoreVal)) AS ?riskScore)
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:healthOfInvestor ?investor ;
          wm:riskScore ?riskScoreVal .
    }
    GROUP BY ?investor
    HAVING (MAX(xsd:decimal(?riskScoreVal)) > 70)
  }

  {
    SELECT ?investor (MAX(xsd:decimal(?diff)) AS ?scenarioChange)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:scenarioRebalancingOfInvestor ?investor ;
          wm:newAllocationPct ?newAllocationPct ;
          wm:currentAllocationPct ?currentAllocationPct .
      BIND (xsd:decimal(?newAllocationPct) - xsd:decimal(?currentAllocationPct) AS ?diff)
    }
    GROUP BY ?investor
  }

  FILTER(?scenarioChange > 20)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?total_holding_gain ?net_cash_flow ?risk_pressure_score WHERE {
  # Base investor
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .

  # Aggregate holdings per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?total_holding_gain) WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:currentValue ?cv ;
               wm:cost ?c .
      BIND( (xsd:decimal(?cv) - xsd:decimal(?c)) AS ?gain )
    } GROUP BY ?investorId
  }

  # Aggregate cash flows per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?net_cash_flow) WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?amount .
    } GROUP BY ?investorId
  }

  # Portfolio health for risk pressure score
  ?ph a wm:PortfolioHealth ;
      wm:investorId ?investorId ;
      wm:riskScore ?riskScore ;
      wm:liquidityScore ?liquidityScore ;
      wm:diversificationScore ?diversificationScore .
  BIND( (xsd:decimal(?riskScore) + (xsd:decimal(100) - xsd:decimal(?liquidityScore)) + (xsd:decimal(100) - xsd:decimal(?diversificationScore))) AS ?risk_pressure_score )

  # Apply filters
  FILTER( ?total_holding_gain < 0 && ?net_cash_flow < 0 && ?risk_pressure_score > 180 )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sector
       (AVG(xsd:decimal(?avgGoalProgress)) AS ?avg_goal_progress)
       (AVG(xsd:decimal(?avgLiquidityScore)) AS ?avg_liquidity_score)
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avgGoalProgress)
    WHERE {
      ?goal a wm:InvestmentGoal .
      ?goal wm:investorId ?investorId .
      ?goal wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?liquidityScore)) AS ?avgLiquidityScore)
    WHERE {
      ?ph a wm:PortfolioHealth .
      ?ph wm:investorId ?investorId .
      ?ph wm:liquidityScore ?liquidityScore .
    }
    GROUP BY ?investorId
  }
  ?holding a wm:PortfolioHolding .
  ?holding wm:investorId ?investorId .
  OPTIONAL {
    ?holding wm:hasSector ?sectorNode .
    ?sectorNode rdfs:label ?sectorLabel .
  }
  BIND(COALESCE(?sectorLabel, "NULL") AS ?sector)
}
GROUP BY ?sector

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
