PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .

  ?holding wm:heldByInvestor ?investor ;
           wm:sector ?holdingSector .
  FILTER(LCASE(STR(?holdingSector)) = "pharma")

  ?alloc wm:allocationOfInvestor ?investor ;
        wm:sector ?allocSector .
  FILTER(LCASE(STR(?allocSector)) = "pharma")

  ?health wm:healthOfInvestor ?investor ;
          wm:diversificationScore ?divScore .
  FILTER(xsd:decimal(?divScore) < 35)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(?goalProgress) AS ?avg_goal_progress)
       (AVG(?riskScore) AS ?avg_risk_score)
       (SUM(?holdingValue) AS ?total_holding_value)
WHERE {
  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:riskTolerance ?rt . }
  BIND(COALESCE(?rt, "NULL") AS ?riskTolerance)

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?progressPct)) AS ?goalProgress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?riskScoreVal)) AS ?riskScore)
    WHERE {
      ?inv wm:hasPortfolioHealth ?ph .
      ?ph wm:riskScore ?riskScoreVal .
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?currVal)) AS ?holdingValue)
    WHERE {
      ?inv wm:hasHolding ?hold .
      ?hold wm:currentValue ?currVal .
    }
    GROUP BY ?inv
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (SUM(xsd:decimal(?holdingSum)) AS ?total_holding_value)
       (SUM(xsd:decimal(?sectorSum)) AS ?total_sector_allocation_investment)
WHERE {
  # Investor base
  ?inv rdf:type wm:Investor ;
       wm:investorId ?investorId .

  # Optional risk tolerance with null preservation
  OPTIONAL { ?inv wm:riskTolerance ?rtRaw . }
  BIND(COALESCE(STR(?rtRaw), "NULL") AS ?riskTolerance)

  # Pre‑aggregated holding values per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?currentValue)) AS ?holdingSum)
    WHERE {
      ?holding rdf:type wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:currentValue ?currentValue .
    }
    GROUP BY ?investorId
  }

  # Pre‑aggregated sector allocation per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?totalInvestment)) AS ?sectorSum)
    WHERE {
      ?alloc rdf:type wm:SectorAllocation ;
            wm:investorId ?investorId ;
            wm:totalInvestment ?totalInvestment .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?month (COUNT(?cashFlowId) AS ?transaction_count) (SUM(xsd:decimal(?amount)) AS ?net_amount)
WHERE {
  {
    ?cf rdf:type wm:CashFlow .
    ?cf wm:cashFlowId ?cashFlowId .
    ?cf wm:amount ?amount .
    OPTIONAL {
      ?cf wm:date ?date .
      BIND(SUBSTR(STR(?date), 1, 7) AS ?monthRaw)
    }
  }
  UNION
  {
    ?cf rdf:type kg:CashFlow .
    ?cf kg:cashFlowId ?cashFlowId .
    ?cf kg:amount ?amount .
    OPTIONAL {
      ?cf kg:date ?date .
      BIND(SUBSTR(STR(?date), 1, 7) AS ?monthRaw)
    }
  }
  BIND(COALESCE(?monthRaw, "NULL") AS ?month)
}
GROUP BY ?month

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?scenario (COUNT(?invId) AS ?investor_count)
WHERE {
  {
    SELECT DISTINCT ?invId ?scenarioRaw
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?invId .
      ?sr a wm:ScenarioRebalancing ;
           wm:investorId ?invId .
      OPTIONAL { ?sr wm:scenario ?scenarioRaw . }
    }
  }
  BIND(COALESCE(STR(?scenarioRaw), "NULL") AS ?scenario)
}
GROUP BY ?scenario

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sectorLabel (COALESCE(?totalHoldingValue, 0) AS ?total_holding_value) (COALESCE(?totalAllocationInvestment, 0) AS ?total_sector_allocation_investment)
WHERE {
  ?sector a wm:Sector .
  OPTIONAL { ?sector rdfs:label ?sectorLabelRaw . }
  BIND(COALESCE(STR(?sectorLabelRaw), "NULL") AS ?sectorLabel)

  OPTIONAL {
    SELECT ?sector (SUM(xsd:decimal(?cv)) AS ?totalHoldingValue)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:hasSector ?sector ;
               wm:currentValue ?cv .
    }
    GROUP BY ?sector
  }

  OPTIONAL {
    SELECT ?sector (SUM(xsd:decimal(?ti)) AS ?totalAllocationInvestment)
    WHERE {
      ?alloc a wm:SectorAllocation ;
            wm:hasSector ?sector ;
            wm:totalInvestment ?ti .
    }
    GROUP BY ?sector
  }
}
ORDER BY ?sectorLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
