PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:category ?invCategory ;
            wm:hasHolding ?holding ;
            wm:hasPortfolioHealth ?health .
  FILTER(LCASE(STR(?invCategory)) = "gold") .

  ?holding rdf:type wm:PortfolioHolding ;
           wm:category ?holdCategory .
  FILTER(LCASE(STR(?holdCategory)) = "gold") .

  ?health rdf:type wm:PortfolioHealth ;
          wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 60) .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?riskScore
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:riskTolerance ?rt ;
            wm:hasPortfolioHealth ?ph .
  ?ph rdf:type wm:PortfolioHealth ;
      wm:riskScore ?riskScore .
  FILTER(LCASE(STR(?rt)) = "conservative")
  FILTER(xsd:decimal(?riskScore) > 75)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment (COUNT(DISTINCT ?investorId) AS ?investor_count)
WHERE {
  {
    SELECT DISTINCT ?investorId ?segment WHERE {
      ?inv rdf:type wm:Investor .
      ?inv wm:investorId ?investorId .
      OPTIONAL { ?inv wm:segment ?invSeg . }
      BIND(COALESCE(STR(?invSeg), "NULL") AS ?segment) .
      ?inv wm:hasHolding ?hold .
      OPTIONAL { ?hold wm:segment ?holdSeg . }
      BIND(COALESCE(STR(?holdSeg), "NULL") AS ?holdSegVal) .
      FILTER(?segment = ?holdSegVal)
    }
  }
}
GROUP BY ?segment

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?missing_investment_type ?missing_sector ?missing_segment ?missing_category WHERE {
  {
    SELECT (COUNT(DISTINCT ?h) AS ?missing_investment_type) WHERE {
      ?h a wm:PortfolioHolding .
      FILTER NOT EXISTS {
        ?h wm:investmentType ?val .
        FILTER (STRLEN(STR(?val)) > 0)
      }
    }
  }
  {
    SELECT (COUNT(DISTINCT ?h) AS ?missing_sector) WHERE {
      ?h a wm:PortfolioHolding .
      FILTER NOT EXISTS {
        ?h wm:sector ?val .
        FILTER (STRLEN(STR(?val)) > 0)
      }
    }
  }
  {
    SELECT (COUNT(DISTINCT ?h) AS ?missing_segment) WHERE {
      ?h a wm:PortfolioHolding .
      FILTER NOT EXISTS {
        ?h wm:segment ?val .
        FILTER (STRLEN(STR(?val)) > 0)
      }
    }
  }
  {
    SELECT (COUNT(DISTINCT ?h) AS ?missing_category) WHERE {
      ?h a wm:PortfolioHolding .
      FILTER NOT EXISTS {
        ?h wm:category ?val .
        FILTER (STRLEN(STR(?val)) > 0)
      }
    }
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (SUM(?rebAmountSum) AS ?total_rebalancing_amount)
       (SUM(?cfAmountSum) AS ?total_cash_flow_amount)
       (SUM(?rebCount) AS ?rebalancing_transaction_count)
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:riskTolerance ?riskTolerance .

  {
    SELECT ?investorId (SUM(xsd:decimal(?rebAmount)) AS ?rebAmountSum) (COUNT(?rebalanceId) AS ?rebCount)
    WHERE {
      ?rebAct a wm:RebalancingAction ;
              wm:investorId ?investorId ;
              wm:amount ?rebAmount ;
              wm:rebalanceId ?rebalanceId .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?cfAmountSum)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?cfAmount .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment
       (SUM(?cashFlowSum) AS ?cash_flow_net_amount)
       (SUM(?scenarioChangeSum) AS ?scenario_change)
       (SUM(?scenarioCount) AS ?scenario_count)
WHERE {
  # Investor with segment
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:segment ?segmentRaw . }
  BIND(COALESCE(?segmentRaw, "NULL") AS ?segment)

  # CashFlow aggregation per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowSum)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?amount .
    }
    GROUP BY ?investorId
  }

  # ScenarioRebalancing aggregation per investor
  {
    SELECT ?investorId
           (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?scenarioChangeSum)
           (COUNT(?scenarioRebalanceId) AS ?scenarioCount)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?investorId ;
          wm:newAllocationPct ?newAlloc ;
          wm:currentAllocationPct ?currAlloc ;
          wm:scenarioRebalanceId ?scenarioRebalanceId .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?segment

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?profile_segment
       (AVG(?inv_progress) AS ?avg_goal_progress)
       (AVG(?ph_risk) AS ?avg_health_risk)
       (AVG(?ph_liq) AS ?avg_liquidity)
WHERE {
  {
    SELECT ?investorId ?profile_segment (AVG(xsd:decimal(?progressPct)) AS ?inv_progress)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:investorId ?investorId .
      ?goal wm:sourceTable ?profile_segment .
      ?goal wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId ?profile_segment
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?riskScore)) AS ?ph_risk) (AVG(xsd:decimal(?liquidityScore)) AS ?ph_liq)
    WHERE {
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:investorId ?investorId .
      ?ph wm:riskScore ?riskScore .
      ?ph wm:liquidityScore ?liquidityScore .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?profile_segment

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT 
  (COALESCE(STR(?riskToleranceRaw), "NULL") AS ?riskTolerance) 
  (SUM(?investorHoldingSum) AS ?totalCurrentHoldingValue)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?currentValue)) AS ?investorHoldingSum) ?riskToleranceRaw
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?investorId .
      OPTIONAL { ?inv wm:riskTolerance ?riskToleranceRaw . }
      ?holding a wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:currentValue ?currentValue .
    }
    GROUP BY ?investorId ?riskToleranceRaw
  }
}
GROUP BY ?riskToleranceRaw

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?time_horizon 
       (AVG(?invAvgScenarioChange) AS ?avg_scenario_change) 
       (AVG(?invAvgSectorAlloc) AS ?avg_sector_allocation)
WHERE {
  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:timeHorizon ?time_horizon_raw . }
  BIND(COALESCE(STR(?time_horizon_raw), "NULL") AS ?time_horizon)

  {
    SELECT ?inv (AVG(xsd:decimal(?change)) AS ?invAvgScenarioChange)
    WHERE {
      ?sr a wm:ScenarioRebalancing .
      ?sr wm:scenarioRebalancingOfInvestor ?inv .
      ?sr wm:newAllocationPct ?new .
      ?sr wm:currentAllocationPct ?current .
      BIND(xsd:decimal(?new) - xsd:decimal(?current) AS ?change)
    }
    GROUP BY ?inv
  }

  {
    SELECT ?inv (AVG(xsd:decimal(?allocationPct)) AS ?invAvgSectorAlloc)
    WHERE {
      ?sa a wm:SectorAllocation .
      ?sa wm:allocationOfInvestor ?inv .
      ?sa wm:allocationPct ?allocationPct .
    }
    GROUP BY ?inv
  }
}
GROUP BY ?time_horizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?profile_category
       (AVG(?goalProgress) AS ?avg_goal_progress)
       (AVG(?riskScore) AS ?avg_health_risk)
       (AVG(?liquidityScore) AS ?avg_liquidity)
WHERE {
  {
    SELECT ?investorId ?profile_category (AVG(xsd:decimal(?progressPct)) AS ?goalProgress)
    WHERE {
      ?goal a wm:InvestmentGoal .
      ?goal wm:investorId ?investorId .
      ?goal wm:progressPct ?progressPct .
      OPTIONAL { ?goal wm:sourceTable ?src . }
      BIND(COALESCE(STR(?src), "NULL") AS ?profile_category)
    }
    GROUP BY ?investorId ?profile_category
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?riskScoreRaw)) AS ?riskScore)
           (AVG(xsd:decimal(?liquidityScoreRaw)) AS ?liquidityScore)
    WHERE {
      ?ph a wm:PortfolioHealth .
      ?ph wm:investorId ?investorId .
      ?ph wm:riskScore ?riskScoreRaw .
      ?ph wm:liquidityScore ?liquidityScoreRaw .
    }
    GROUP BY ?investorId
  }
  FILTER EXISTS { ?cf a wm:CashFlow ; wm:investorId ?investorId . }
  FILTER EXISTS { ?inv a wm:Investor ; wm:investorId ?investorId . }
}
GROUP BY ?profile_category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?total_holding_gain ?net_cash_flow
WHERE {
  {
    SELECT ?inv ?investorId (SUM(xsd:decimal(?gain)) AS ?total_holding_gain)
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?investorId .
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?inv ;
               wm:currentValue ?curr ;
               wm:cost ?cost .
      BIND (xsd:decimal(?curr) - xsd:decimal(?cost) AS ?gain)
    }
    GROUP BY ?inv ?investorId
  }
  {
    SELECT ?inv (SUM(xsd:decimal(?amount)) AS ?net_cash_flow)
    WHERE {
      ?inv a wm:Investor .
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:amount ?amount .
    }
    GROUP BY ?inv
  }
  FILTER(?total_holding_gain < 0 && ?net_cash_flow < 0)
  OPTIONAL { ?inv wm:investorName ?investorName . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(?avgScenarioDiff) AS ?avg_scenario_change)
       (AVG(?avgRebalancingDiff) AS ?avg_rebalancing_gap)
       (AVG(?avgRiskScore) AS ?avg_health_risk)
       (AVG(?avgProgressPct) AS ?avg_goal_match)
WHERE {
  {
    SELECT ?inv (AVG(xsd:decimal(?new) - xsd:decimal(?current)) AS ?avgScenarioDiff)
    WHERE {
      ?inv a wm:Investor .
      ?sr wm:scenarioRebalancingOfInvestor ?inv .
      ?sr wm:newAllocationPct ?new .
      ?sr wm:currentAllocationPct ?current .
    }
    GROUP BY ?inv
  }
  {
    SELECT ?inv (AVG(xsd:decimal(?target) - xsd:decimal(?currentRA)) AS ?avgRebalancingDiff)
    WHERE {
      ?inv a wm:Investor .
      ?ra wm:rebalancingActionOfInvestor ?inv .
      ?ra wm:targetAllocationPct ?target .
      ?ra wm:currentAllocationPct ?currentRA .
    }
    GROUP BY ?inv
  }
  {
    SELECT ?inv (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
    WHERE {
      ?inv a wm:Investor .
      ?ph wm:healthOfInvestor ?inv .
      ?ph wm:riskScore ?riskScore .
    }
    GROUP BY ?inv
  }
  {
    SELECT ?inv (AVG(xsd:decimal(?progressPct)) AS ?avgProgressPct)
    WHERE {
      ?inv a wm:Investor .
      ?ig wm:belongsToInvestor ?inv .
      ?ig wm:progressPct ?progressPct .
    }
    GROUP BY ?inv
  }
  ?inv wm:riskTolerance ?riskTolerance .
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?total_goal_shortfall ?total_holding_gain ?net_cash_flow
WHERE {
  {
    SELECT ?investorId ?investorName
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?investorId ;
           wm:investorName ?investorName .
    }
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?shortfall)) AS ?total_goal_shortfall)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(?gain) AS ?total_holding_gain)
    WHERE {
      ?hold a wm:PortfolioHolding ;
            wm:investorId ?investorId ;
            wm:currentValue ?currentValue ;
            wm:cost ?cost .
      BIND (xsd:decimal(?currentValue) - xsd:decimal(?cost) AS ?gain)
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?net_cash_flow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  FILTER ( ?total_goal_shortfall > 0 && ?total_holding_gain < 0 && ?net_cash_flow < 10000 )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COALESCE(?cat, "NULL") AS ?category)
       (COALESCE(?rt, "NULL") AS ?riskTolerance)
       (COUNT(?investorId) AS ?investor_count)
WHERE {
  {
    SELECT DISTINCT ?inv ?investorId
    WHERE {
      ?holding wm:heldByInvestor ?inv .
      ?holding wm:returnsPct ?ret .
      FILTER(xsd:decimal(?ret) < 0) .
      ?inv rdf:type wm:Investor .
      ?inv wm:investorId ?investorId .
    }
  }
  OPTIONAL { ?inv wm:category ?cat . }
  OPTIONAL { ?inv wm:riskTolerance ?rt . }
}
GROUP BY ?cat ?rt

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?holdingId ?investmentName
WHERE {
  ?holding a wm:PortfolioHolding ;
           wm:holdingId ?holdingId ;
           wm:investmentName ?investmentName .
  FILTER NOT EXISTS {
    ?holding wm:heldByInvestor ?inv .
    ?inv a wm:Investor .
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

# Holding gain condition omitted because the schema does not provide a holding gain property.
SELECT ?investorId ?investorName ?netCashFlow WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:hasInvestmentGoal ?goal ;
       wm:hasPortfolioHealth ?ph .

  ?goal wm:shortfall ?shortfall .
  FILTER(xsd:decimal(?shortfall) > 0)

  ?ph wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 65)

  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
    WHERE {
      ?invCash a wm:Investor ;
               wm:investorId ?investorId ;
               wm:hasCashFlow ?cf .
      ?cf wm:amount ?amount .
    }
    GROUP BY ?investorId
    HAVING (SUM(xsd:decimal(?amount)) < 10000)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_tolerance
       (AVG(?avgProgressInvestor) AS ?avg_goal_progress)
       (AVG(?avgGainInvestor) AS ?avg_holding_gain)
       (AVG(xsd:decimal(?riskScore)) AS ?avg_risk_score)
       (AVG(xsd:decimal(?liquidityScore)) AS ?avg_liquidity)
WHERE {
  # Base investor with risk tolerance
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:riskTolerance ?riskTolerance .
  BIND(?riskTolerance AS ?risk_tolerance)

  # Portfolio health (required)
  ?health a wm:PortfolioHealth ;
          wm:investorId ?investorId ;
          wm:riskScore ?riskScore ;
          wm:liquidityScore ?liquidityScore .

  # Subquery: average goal progress per investor
  {
    SELECT ?investorId (AVG(xsd:decimal(?progress)) AS ?avgProgressInvestor)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:progressPct ?progress .
    }
    GROUP BY ?investorId
  }

  # Subquery: average holding gain per investor
  {
    SELECT ?investorId (AVG(xsd:decimal(?gain)) AS ?avgGainInvestor)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:currentValue ?curr ;
               wm:cost ?cost .
      BIND(xsd:decimal(?curr) - xsd:decimal(?cost) AS ?gain)
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?risk_tolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?combined_amount WHERE {
  ?inv a wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?total_holding_gain) WHERE {
      ?holding a wm:PortfolioHolding .
      ?holding wm:investorId ?investorId .
      ?holding wm:currentValue ?currentValue .
      ?holding wm:cost ?cost .
    } GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?net_cash_flow) WHERE {
      ?cf a wm:CashFlow .
      ?cf wm:investorId ?investorId .
      ?cf wm:amount ?amount .
    } GROUP BY ?investorId
  }

  BIND( (COALESCE(?total_holding_gain, 0) + COALESCE(?net_cash_flow, 0)) AS ?combined_amount )
}
ORDER BY DESC(?combined_amount) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?avg_progress ?total_withdrawal
WHERE {
  # Base Investor with risk filter
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:riskTolerance ?riskTol .
  FILTER ( xsd:decimal(?riskTol) > 50 )

  # Average progress per investor (must be < 40)
  {
    SELECT ?inv (AVG(xsd:decimal(?prog)) AS ?avg_progress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv ;
            wm:progressPct ?prog .
    }
    GROUP BY ?inv
    HAVING (AVG(xsd:decimal(?prog)) < 40)
  }

  # Total withdrawal amount per investor
  {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?total_withdrawal)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:type ?cfType ;
          wm:amount ?amt .
      FILTER ( LCASE(STR(?cfType)) = "withdrawal" )
    }
    GROUP BY ?inv
  }
}
ORDER BY DESC(?total_withdrawal) ?investorId
LIMIT 5

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment ?sector (COUNT(?investorId) AS ?investor_count)
WHERE {
  {
    SELECT DISTINCT ?investorId ?segment ?sector
    WHERE {
      ?alloc a wm:SectorAllocation .
      ?alloc wm:allocationPct ?allocPct .
      FILTER(xsd:decimal(?allocPct) > 25) .
      ?alloc wm:allocationOfInvestor ?investor .
      ?investor wm:investorId ?investorId .

      OPTIONAL { ?investor wm:segment ?segmentRaw . }
      BIND(COALESCE(STR(?segmentRaw), "NULL") AS ?segment) .

      OPTIONAL { ?alloc wm:sector ?sectorRaw . }
      BIND(COALESCE(STR(?sectorRaw), "NULL") AS ?sector) .
    }
  }
}
GROUP BY ?segment ?sector

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category ?sector (COUNT(DISTINCT ?investorId) AS ?investor_count)
WHERE {
  {
    SELECT DISTINCT ?investor ?investorId ?category
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorId .
      OPTIONAL { ?investor wm:category ?catRaw . }
      BIND(COALESCE(STR(?catRaw), "NULL") AS ?category)

      ?ph rdf:type wm:PortfolioHealth ;
          wm:healthOfInvestor ?investor ;
          wm:riskScore ?riskScore .
      FILTER(?riskScore > 70)

      FILTER EXISTS {
        ?h rdf:type wm:PortfolioHolding ;
           wm:heldByInvestor ?investor ;
           wm:returnsPct ?ret .
        FILTER(?ret < 0)
      }
    }
  }

  ?holding rdf:type wm:PortfolioHolding ;
           wm:heldByInvestor ?investor ;
           wm:returnsPct ?returnsPct .
  FILTER(?returnsPct < 0)

  OPTIONAL {
    ?holding wm:hasSector ?sectorNode .
    OPTIONAL { ?sectorNode rdfs:label ?sectorLabel . }
  }
  BIND(COALESCE(STR(?sectorLabel), "NULL") AS ?sector)
}
GROUP BY ?category ?sector

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cash_source (AVG(?invChange) AS ?average_scenario_change)
WHERE {
  ?cf a wm:CashFlow ;
      wm:investorId ?investorId ;
      wm:source ?cash_source .
  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?newAllocationPct) - xsd:decimal(?currentAllocationPct)) AS ?invChange)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?investorId ;
          wm:newAllocationPct ?newAllocationPct ;
          wm:currentAllocationPct ?currentAllocationPct .
    }
    GROUP BY ?investorId
  }
  FILTER (BOUND(?invChange))
}
GROUP BY ?cash_source

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName (COUNT(?holding) AS ?matching_sector_count)
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:hasHolding ?holding ;
       wm:hasSectorAllocation ?alloc .
  ?holding wm:sector ?sector .
  ?alloc wm:sector ?sector .
}
GROUP BY ?investorId ?investorName
HAVING (COUNT(?holding) > 0)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  ?inv wm:investorName ?investorName .

  FILTER EXISTS {
    ?inv wm:hasInvestmentGoal ?goal .
    ?goal wm:shortfall ?shortfall .
    FILTER(xsd:decimal(?shortfall) > 0)
  }

  FILTER EXISTS {
    ?inv wm:hasHolding ?holding .
    ?holding wm:returnsPct ?returnsPct .
    FILTER(xsd:decimal(?returnsPct) < 0)
  }

  FILTER EXISTS {
    ?inv wm:hasSectorAllocation ?alloc .
    ?alloc wm:allocationPct ?allocationPct .
    FILTER(xsd:decimal(?allocationPct) > 40)
  }

  FILTER EXISTS {
    ?inv wm:hasPortfolioHealth ?ph .
    ?ph wm:diversificationScore ?divScore .
    FILTER(xsd:decimal(?divScore) < 30)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?time_horizon
       (SUM(?cash_flow_net_amount_inner) AS ?cash_flow_net_amount)
       (AVG(?scenario_change_inner) AS ?scenario_change)
       (SUM(?scenario_count_inner) AS ?scenario_count)
WHERE {
  # Investor and its time horizon
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:timeHorizon ?timeHorizonRaw . }
  BIND(COALESCE(STR(?timeHorizonRaw), "NULL") AS ?time_horizon)

  # Cash‑flow aggregation per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cash_flow_net_amount_inner)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?amount .
    }
    GROUP BY ?investorId
  }

  # Scenario‑rebalance aggregation per investor
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?diff)) AS ?scenario_change_inner)
           (COUNT(?scenarioRebalanceId) AS ?scenario_count_inner)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?investorId ;
          wm:newAllocationPct ?newAllocationPct ;
          wm:currentAllocationPct ?currentAllocationPct ;
          wm:scenarioRebalanceId ?scenarioRebalanceId .
      BIND((xsd:decimal(?newAllocationPct) - xsd:decimal(?currentAllocationPct)) AS ?diff)
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?time_horizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:riskTolerance ?riskTolerance .
  FILTER(LCASE(STR(?riskTolerance)) = "moderate") .

  ?goal a wm:InvestmentGoal ;
        wm:belongsToInvestor ?inv ;
        wm:investmentGoal ?goalType .
  FILTER(LCASE(STR(?goalType)) = "income generation") .

  ?cf a wm:CashFlow ;
      wm:cashFlowOfInvestor ?inv ;
      wm:type ?cfType .
  FILTER(LCASE(STR(?cfType)) = "dividend reinvestment") .
}
GROUP BY ?investorId ?investorName

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .

  FILTER EXISTS {
    ?investor wm:hasInvestmentGoal ?goal .
    ?goal wm:progressPct ?progressPct .
    FILTER (xsd:decimal(?progressPct) < 20)
  }

  FILTER EXISTS {
    ?investor wm:hasPortfolioHealth ?ph .
    ?ph wm:riskScore ?riskScore .
    FILTER (xsd:decimal(?riskScore) > 70)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?combined_amount WHERE {
  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:investorId ?investorId . }
  OPTIONAL { ?inv wm:investorName ?investorName . }

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?cfAmount)) AS ?cash_flow_total) WHERE {
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:amount ?cfAmount .
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?raAmount)) AS ?rebalancing_total) WHERE {
      ?inv wm:hasRebalancingAction ?ra .
      ?ra wm:amount ?raAmount .
    } GROUP BY ?inv
  }

  BIND( COALESCE(?cash_flow_total, 0) + COALESCE(?rebalancing_total, 0) AS ?combined_amount )
}
ORDER BY DESC(?combined_amount) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
       (COUNT(DISTINCT ?cashFlowId) AS ?cash_flow_count)
       (COUNT(DISTINCT ?holdingId) AS ?negative_holding_count)
       (COUNT(DISTINCT ?goalId) AS ?underfunded_goal_count)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasCashFlow ?cashFlow ;
            wm:hasHolding ?holding ;
            wm:hasInvestmentGoal ?goal .

  ?cashFlow wm:cashFlowId ?cashFlowId .

  ?holding wm:holdingId ?holdingId ;
           wm:returnsPct ?returnsPct ;
           wm:purchaseDate ?purchaseDate .
  FILTER(xsd:decimal(?returnsPct) < 0) .
  FILTER(CONTAINS(LCASE(STR(?purchaseDate)), "2025")) .

  ?goal wm:goalId ?goalId ;
        wm:shortfall ?shortfall .
  FILTER(xsd:decimal(?shortfall) > 0) .
}
GROUP BY ?investorId ?investorName

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName ?investorId ?average_shortfall ?total_holding_gain
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  {
    SELECT ?investorId (SUM(xsd:decimal(?cv) - xsd:decimal(?c)) AS ?total_holding_gain)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:currentValue ?cv ;
               wm:cost ?c .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (AVG(xsd:decimal(?sf)) AS ?average_shortfall)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:shortfall ?sf .
    }
    GROUP BY ?investorId
  }

  FILTER(?total_holding_gain < 0)
}
ORDER BY DESC(?average_shortfall) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?risk_pressure_score ?avg_progress_pct
WHERE {
  # Base Investor
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  # Risk pressure score per investor
  {
    SELECT ?investorId ( (xsd:decimal(?riskScore) + (100 - xsd:decimal(?liquidityScore)) + (100 - xsd:decimal(?diversificationScore))) AS ?risk_pressure_score )
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:investorId ?investorId ;
          wm:riskScore ?riskScore ;
          wm:liquidityScore ?liquidityScore ;
          wm:diversificationScore ?diversificationScore .
    }
    GROUP BY ?investorId ?riskScore ?liquidityScore ?diversificationScore
  }

  # Average progressPct per investor
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avg_progress_pct)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
  }

  FILTER ( ?risk_pressure_score > 220 && ?avg_progress_pct < 40 )
}
ORDER BY ?investorId

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName ?totalDividends WHERE {
  {
    SELECT ?inv (SUM(xsd:decimal(?amount)) AS ?totalDividends) WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:type ?type ;
          wm:amount ?amount .
      FILTER(LCASE(STR(?type)) = "dividend")
    }
    GROUP BY ?inv
  }
  {
    SELECT DISTINCT ?inv WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:healthOfInvestor ?inv ;
          wm:diversificationScore ?divScore .
      FILTER(xsd:decimal(?divScore) < 30)
    }
  }
  ?inv a wm:Investor ;
       wm:investorName ?investorName .
}
ORDER BY DESC(?totalDividends) ?investorName
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?avg_progress_pct ?total_cash_flow
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avg_progress_pct)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
    HAVING (AVG(xsd:decimal(?progressPct)) < 40)
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?total_cash_flow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?amount .
    }
    GROUP BY ?investorId
    HAVING (SUM(xsd:decimal(?amount)) < 0)
  }
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:riskTolerance ?riskTol .
  FILTER(LCASE(STR(?riskTol)) = "conservative") .

  ?holding a wm:PortfolioHolding ;
           wm:investorId ?investorId ;
           wm:investmentName ?invName .
  FILTER(LCASE(STR(?invName)) = "government bond") .

  ?reb a wm:RebalancingAction ;
       wm:investorId ?investorId ;
       wm:logic ?rebLogic .
  FILTER(LCASE(STR(?rebLogic)) = "calendar") .
}
GROUP BY ?investorId ?investorName

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?risk_band (SUM(?holdingValue) AS ?total_holding_value) (SUM(?sectorInvest) AS ?total_sector_allocation_investment)
WHERE {
  {
    SELECT ?investorId ?risk_band (SUM(xsd:decimal(?cv)) AS ?holdingValue)
    WHERE {
      ?ph a wm:PortfolioHolding .
      ?ph wm:investorId ?investorId .
      OPTIONAL { ?ph wm:investmentType ?risk_bandRaw . }
      BIND(COALESCE(STR(?risk_bandRaw), "NULL") AS ?risk_band) .
      ?ph wm:currentValue ?cv .
    }
    GROUP BY ?investorId ?risk_band
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?ti)) AS ?sectorInvest)
    WHERE {
      ?sa a wm:SectorAllocation .
      ?sa wm:investorId ?investorId .
      ?sa wm:totalInvestment ?ti .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?risk_band

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investment_type
       (SUM(xsd:decimal(?cost)) AS ?total_cost)
       (SUM(xsd:decimal(?currentValue)) AS ?total_current_value)
       (SUM(xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?total_holding_gain)
WHERE {
  ?h a wm:PortfolioHolding ;
     wm:cost ?cost ;
     wm:currentValue ?currentValue .
  OPTIONAL { ?h wm:investmentType ?invTypeLiteral . }
  OPTIONAL {
    ?h wm:hasInvestmentType ?invType .
    OPTIONAL { ?invType rdfs:label ?invLabel . }
  }
  BIND(COALESCE(?invLabel, ?invTypeLiteral, "NULL") AS ?investment_type)
}
GROUP BY ?investment_type

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category (COALESCE(?invCount, 0) AS ?profileCategoryCount) (COALESCE(?holdCount, 0) AS ?holdingCategoryCount)
WHERE {
  # All distinct categories appearing in either Investors or PortfolioHoldings
  {
    SELECT DISTINCT ?category WHERE {
      { ?inv a wm:Investor ; wm:category ?category . }
      UNION
      { ?hold a wm:PortfolioHolding ; wm:category ?category . }
    }
  }
  # Count Investors per category
  OPTIONAL {
    SELECT ?category (COUNT(?inv) AS ?invCount) WHERE {
      ?inv a wm:Investor ; wm:category ?category .
    } GROUP BY ?category
  }
  # Count PortfolioHoldings per category
  OPTIONAL {
    SELECT ?category (COUNT(?hold) AS ?holdCount) WHERE {
      ?hold a wm:PortfolioHolding ; wm:category ?category .
    } GROUP BY ?category
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  ?goal a wm:InvestmentGoal ;
        wm:belongsToInvestor ?inv ;
        wm:timeToGoalMonths ?months .
  FILTER(xsd:decimal(?months) <= 12)

  ?ra a wm:RebalancingAction ;
      wm:rebalancingActionOfInvestor ?inv ;
      wm:action ?action .
  FILTER(LCASE(STR(?action)) = "de-risking")
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?total_holding_value ?total_shortfall ((?total_holding_value + ?total_shortfall) AS ?combined_metric)
WHERE {
  # Investor core data
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  # Portfolio health with riskScore filter
  ?ph a wm:PortfolioHealth ;
      wm:investorId ?investorId ;
      wm:riskScore ?riskScore .
  FILTER (xsd:decimal(?riskScore) > 60)

  # Aggregated holding value per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?holdingValue)) AS ?total_holding_value)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:currentValue ?holdingValue .
    }
    GROUP BY ?investorId
  }

  # Aggregated shortfall per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?shortfallVal)) AS ?total_shortfall)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:shortfall ?shortfallVal .
    }
    GROUP BY ?investorId
  }
}
ORDER BY DESC(?combined_metric) ?investorId
LIMIT 5

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (SUM(?holdingSum) AS ?total_holding_value)
       (SUM(?sectorSum) AS ?total_sector_allocation)
       (SUM(?cashSum) AS ?total_cash_flow_amount)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?cv)) AS ?holdingSum)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasHolding ?holding .
      ?holding wm:currentValue ?cv .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?ti)) AS ?sectorSum)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasSectorAllocation ?alloc .
      ?alloc wm:totalInvestment ?ti .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?amt)) AS ?cashSum)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId ;
                wm:hasCashFlow ?cf .
      ?cf wm:amount ?amt .
    }
    GROUP BY ?investorId
  }
  OPTIONAL {
    ?inv a wm:Investor ;
         wm:investorId ?investorId .
    OPTIONAL { ?inv wm:category ?catRaw . }
    BIND(COALESCE(STR(?catRaw), "NULL") AS ?category)
  }
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?time_horizon
       (AVG(?allocAvg) AS ?allocation_concentration)
       (AVG(?returnAvg) AS ?holding_return)
       (SUM(?valueSum) AS ?holding_value)
WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .

  OPTIONAL { ?inv wm:timeHorizon ?time_horizon_raw . }
  BIND(COALESCE(STR(?time_horizon_raw), "NULL") AS ?time_horizon)

  {
    SELECT ?investorId (AVG(xsd:decimal(?allocationPct)) AS ?allocAvg)
    WHERE {
      ?allocRec rdf:type wm:SectorAllocation .
      ?allocRec wm:investorId ?investorId ;
                wm:allocationPct ?allocationPct .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (AVG(xsd:decimal(?returnsPct)) AS ?returnAvg)
    WHERE {
      ?holdRec rdf:type wm:PortfolioHolding .
      ?holdRec wm:investorId ?investorId ;
               wm:returnsPct ?returnsPct .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?currentValue)) AS ?valueSum)
    WHERE {
      ?holdRec2 rdf:type wm:PortfolioHolding .
      ?holdRec2 wm:investorId ?investorId ;
                wm:currentValue ?currentValue .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?time_horizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?total_shortfall ?total_cash_flow ?de_risk_count
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?shortfall)) AS ?total_shortfall)
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?investorId ;
           wm:hasInvestmentGoal ?goal .
      ?goal wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?total_cash_flow)
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?investorId ;
           wm:hasCashFlow ?cf .
      ?cf wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (COUNT(?ra) AS ?de_risk_count)
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?investorId ;
           wm:hasRebalancingAction ?ra .
      ?ra wm:action ?action .
      FILTER(LCASE(STR(?action)) = "de-risking")
    }
    GROUP BY ?investorId
  }
  ?invName a wm:Investor ;
           wm:investorId ?investorId ;
           wm:investorName ?investorName .
  FILTER(?total_shortfall > 0)
  FILTER(?total_cash_flow < 0)
  FILTER(?de_risk_count >= 1)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?time_horizon
       (SUM(?inflow) AS ?total_inflow)
       (SUM(?outflow) AS ?total_outflow)
       (SUM(?goalShortfall) AS ?total_goal_shortfall)
       (SUM(?dividends) AS ?total_dividends)
       (SUM(?taxesPaid) AS ?total_taxes_paid)
WHERE {
  # Investor and its time horizon
  ?inv a wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:timeHorizon ?time_horizon_raw . }
  BIND(COALESCE(STR(?time_horizon_raw), "NULL") AS ?time_horizon)

  # Inflow per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?amtIn)) AS ?inflow)
    WHERE {
      ?cf a wm:CashFlow .
      ?cf wm:investorId ?investorId .
      ?cf wm:amount ?amtIn .
      ?cf wm:type ?typeIn .
      FILTER(LCASE(STR(?typeIn)) = "inflow")
    }
    GROUP BY ?investorId
  }

  # Outflow per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?amtOut)) AS ?outflow)
    WHERE {
      ?cf2 a wm:CashFlow .
      ?cf2 wm:investorId ?investorId .
      ?cf2 wm:amount ?amtOut .
      ?cf2 wm:type ?typeOut .
      FILTER(LCASE(STR(?typeOut)) = "outflow")
    }
    GROUP BY ?investorId
  }

  # Goal shortfall per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?sf)) AS ?goalShortfall)
    WHERE {
      ?goal a wm:InvestmentGoal .
      ?goal wm:investorId ?investorId .
      ?goal wm:shortfall ?sf .
    }
    GROUP BY ?investorId
  }

  # Dividends per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?div)) AS ?dividends)
    WHERE {
      ?ph a wm:PortfolioHolding .
      ?ph wm:investorId ?investorId .
      ?ph wm:dividends ?div .
    }
    GROUP BY ?investorId
  }

  # Taxes paid per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?tax)) AS ?taxesPaid)
    WHERE {
      ?ph2 a wm:PortfolioHolding .
      ?ph2 wm:investorId ?investorId .
      ?ph2 wm:taxesPaid ?tax .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?time_horizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(?avgAllocPctInv) AS ?avg_allocation_concentration)
       (AVG(?avgReturnInv) AS ?avg_holding_return)
       (SUM(?totalValueInv) AS ?total_holding_value)
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:riskTolerance ?riskTolerance .

  {
    SELECT ?investorId (AVG(xsd:decimal(?allocationPct)) AS ?avgAllocPctInv)
    WHERE {
      ?sa a wm:SectorAllocation ;
          wm:investorId ?investorId ;
          wm:allocationPct ?allocationPct .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId
           (AVG(xsd:decimal(?returnsPct)) AS ?avgReturnInv)
           (SUM(xsd:decimal(?currentValue)) AS ?totalValueInv)
    WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:investorId ?investorId ;
          wm:returnsPct ?returnsPct ;
          wm:currentValue ?currentValue .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?avg_sharpe_ratio ?avg_volatility_pct ?total_holding_gain ?net_cash_flow
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .

  {
    SELECT ?investorId (AVG(xsd:decimal(?sharpe)) AS ?avg_sharpe_ratio) (AVG(xsd:decimal(?vol)) AS ?avg_volatility_pct)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv ;
            wm:avgSharpeRatio ?sharpe ;
            wm:avgVolatilityPct ?vol .
      ?inv wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?total_holding_gain)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?inv ;
               wm:currentValue ?curr ;
               wm:cost ?cost .
      ?inv wm:investorId ?investorId .
      BIND((xsd:decimal(?curr) - xsd:decimal(?cost)) AS ?gain)
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?amt)) AS ?net_cash_flow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:amount ?amt .
      ?inv wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  FILTER(?avg_sharpe_ratio < 0 && ?avg_volatility_pct > 10 && ?total_holding_gain < 0 && ?net_cash_flow < 1000000)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ( (SUM(xsd:decimal(?cfAmount)) + SUM(xsd:decimal(?raAmount)) + SUM(?scenarioChange)) AS ?totalScore )
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  OPTIONAL {
    ?cf a wm:CashFlow ;
        wm:cashFlowOfInvestor ?inv ;
        wm:amount ?cfAmount .
  }

  OPTIONAL {
    ?ra a wm:RebalancingAction ;
        wm:rebalancingActionOfInvestor ?inv ;
        wm:amount ?raAmount .
  }

  OPTIONAL {
    ?sr a wm:ScenarioRebalancing ;
        wm:scenarioRebalancingOfInvestor ?inv ;
        wm:newAllocationPct ?newPct ;
        wm:currentAllocationPct ?curPct .
    BIND (xsd:decimal(?newPct) - xsd:decimal(?curPct) AS ?scenarioChange)
  }
}
GROUP BY ?investorId ?investorName
ORDER BY DESC(?totalScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (SUM(?holdingGain) AS ?total_holding_gain)
       (SUM(?cashFlowAmt) AS ?net_cash_flow)
       (AVG(?goalProgress) AS ?avg_progress_pct)
       (AVG(?riskScoreAvg) AS ?avg_risk_score)
WHERE {
  # Investor and its category
  ?inv rdf:type wm:Investor .
  OPTIONAL { ?inv wm:category ?catRaw . }
  BIND(COALESCE(STR(?catRaw), "NULL") AS ?category)

  # Link investor to its identifier
  ?inv wm:investorId ?investorId .

  # Holdings aggregation per investor
  {
    SELECT ?investorId (SUM( (xsd:decimal(?currentValue) - xsd:decimal(?cost) + xsd:decimal(?dividendsVal) - xsd:decimal(?taxesPaidVal)) ) AS ?holdingGain)
    WHERE {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:investorId ?investorId .
      ?holding wm:currentValue ?currentValue .
      ?holding wm:cost ?cost .
      OPTIONAL { ?holding wm:dividends ?dividends . }
      OPTIONAL { ?holding wm:taxesPaid ?taxesPaid . }
      BIND(COALESCE(xsd:decimal(?dividends), 0) AS ?dividendsVal)
      BIND(COALESCE(xsd:decimal(?taxesPaid), 0) AS ?taxesPaidVal)
    } GROUP BY ?investorId
  }

  # CashFlow aggregation per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowAmt)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:investorId ?investorId .
      ?cf wm:amount ?amount .
    } GROUP BY ?investorId
  }

  # InvestmentGoal aggregation per investor
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?goalProgress)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:investorId ?investorId .
      ?goal wm:progressPct ?progressPct .
    } GROUP BY ?investorId
  }

  # PortfolioHealth aggregation per investor
  {
    SELECT ?investorId (AVG(xsd:decimal(?riskScore)) AS ?riskScoreAvg)
    WHERE {
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:investorId ?investorId .
      ?ph wm:riskScore ?riskScore .
    } GROUP BY ?investorId
  }
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName ?total2025
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?amt)) AS ?total2025)
    WHERE {
      ?investor a wm:Investor .
      ?cashFlow wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amt ;
                wm:date ?date .
      FILTER (STRSTARTS(STR(?date), "2025"))
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?prog)) AS ?avgProg)
    WHERE {
      ?investor a wm:Investor .
      ?goal wm:belongsToInvestor ?investor ;
            wm:progressPct ?prog .
    }
    GROUP BY ?investor
    HAVING (AVG(xsd:decimal(?prog)) < 40)
  }
  ?investor wm:investorName ?investorName .
}
ORDER BY DESC(?total2025)
LIMIT 5

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
