PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?investorId) AS ?investor_count)
WHERE {
  {
    SELECT DISTINCT ?investorId
    WHERE {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      FILTER NOT EXISTS { ?holding wm:sector ?sector . }
    }
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?categoryLabel 
       (SUM(IF(LCASE(STR(?type)) = "deposit", xsd:decimal(?amount), 0)) AS ?totalDeposit) 
       (SUM(IF(LCASE(STR(?type)) = "withdrawal", xsd:decimal(?amount), 0)) AS ?totalWithdrawal)
WHERE {
  ?inv a wm:Investor ;
       wm:hasCategory ?cat ;
       wm:hasCashFlow ?cf .
  ?cat a wm:Category ;
       rdfs:label ?categoryLabel .
  ?cf a wm:CashFlow ;
      wm:amount ?amount ;
      wm:type ?type .
}
GROUP BY ?categoryLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName (SUM(xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?total_holding_gain)
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName .
  ?holding rdf:type wm:PortfolioHolding ;
           wm:heldByInvestor ?investor ;
           wm:currentValue ?currentValue ;
           wm:cost ?cost .
}
GROUP BY ?investorId ?investorName
ORDER BY DESC(?total_holding_gain) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
  ?riskTolerance
  ?investmentGoal
  (COUNT(?inv) AS ?investorCount)
WHERE {
  ?inv rdf:type wm:Investor .

  OPTIONAL { ?inv wm:riskTolerance ?rtRaw . }
  BIND(COALESCE(STR(?rtRaw), "NULL") AS ?riskTolerance) .

  OPTIONAL { ?inv wm:investmentGoal ?igRaw . }
  BIND(COALESCE(STR(?igRaw), "NULL") AS ?investmentGoal) .

  FILTER EXISTS { ?inv wm:hasHolding ?holding . }
  FILTER EXISTS { ?inv wm:hasSectorAllocation ?allocation . }
  FILTER EXISTS { ?inv wm:hasCashFlow ?cashflow . }
}
GROUP BY ?riskTolerance ?investmentGoal

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance (AVG(?avgGoalProgressInv) AS ?avgGoalProgress) (AVG(?avgRiskInv) AS ?avgPortfolioRisk)
WHERE {
  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:riskTolerance ?rtRaw . }
  BIND(COALESCE(STR(?rtRaw), "NULL") AS ?riskTolerance)

  {
    SELECT ?inv (AVG(xsd:decimal(?progressPct)) AS ?avgGoalProgressInv)
    WHERE {
      ?goal a wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?inv .
      ?goal wm:progressPct ?progressPct .
    }
    GROUP BY ?inv
  }

  {
    SELECT ?inv (AVG(xsd:decimal(?riskScore)) AS ?avgRiskInv)
    WHERE {
      ?ph a wm:PortfolioHealth .
      ?ph wm:healthOfInvestor ?inv .
      ?ph wm:riskScore ?riskScore .
    }
    GROUP BY ?inv
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?total_holding_gain ?total_goal_shortfall ?total_cash_flow
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?total_holding_gain)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:currentValue ?curr ;
               wm:cost ?cost .
      BIND( (xsd:decimal(?curr) - xsd:decimal(?cost)) AS ?gain )
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?shortfall)) AS ?total_goal_shortfall)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?total_cash_flow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?amount .
    }
    GROUP BY ?investorId
  }

  FILTER( ?total_holding_gain < 0 && ?total_goal_shortfall > 0 && ?total_cash_flow < 0 )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sector (COUNT(?investorId) AS ?investor_count)
WHERE {
  ?sa a wm:SectorAllocation ;
      wm:sector ?sector ;
      wm:allocationPct ?allocPct ;
      wm:investorId ?investorId .
  FILTER(xsd:decimal(?allocPct) > 30) .

  ?ph a wm:PortfolioHealth ;
      wm:investorId ?investorId ;
      wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 70) .
}
GROUP BY ?sector
ORDER BY DESC(?investor_count) ?sector
LIMIT 5

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investment_type
       ?avg_riskScore
       ?avg_liquidityScore
       ?avg_diversificationScore
       ?avg_goalMatchPct
WHERE {
  {
    SELECT ?src
           (AVG(xsd:decimal(?riskScore)) AS ?avg_riskScore)
           (AVG(xsd:decimal(?liquidityScore)) AS ?avg_liquidityScore)
           (AVG(xsd:decimal(?diversificationScore)) AS ?avg_diversificationScore)
           (AVG(xsd:decimal(?goalMatchPct)) AS ?avg_goalMatchPct)
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:sourceTable ?src ;
          wm:riskScore ?riskScore ;
          wm:liquidityScore ?liquidityScore ;
          wm:diversificationScore ?diversificationScore ;
          wm:goalMatchPct ?goalMatchPct .
    }
    GROUP BY ?src
  }
  ?inv a wm:InvestmentType ;
       rdfs:label ?src .
  BIND(?src AS ?investment_type)
}
ORDER BY ?investment_type

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (AVG(?avgScenarioChange) AS ?avg_scenario_change)
       (AVG(?avgRebalancingGap) AS ?avg_rebalancing_gap)
       (AVG(?avgHealthRisk) AS ?avg_health_risk)
       (AVG(?avgGoalMatch) AS ?avg_goal_match)
WHERE {
  # Investor and its category
  ?inv a wm:Investor ;
       wm:investorId ?invId .
  OPTIONAL { ?inv wm:category ?catRaw . }
  BIND(COALESCE(STR(?catRaw), "NULL") AS ?category)

  # Scenario Rebalancing per‑investor aggregation
  {
    SELECT ?invId (AVG(xsd:decimal(?scenarioChange)) AS ?avgScenarioChange)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?invId ;
          wm:newAllocationPct ?new ;
          wm:currentAllocationPct ?cur .
      BIND(xsd:decimal(?new) - xsd:decimal(?cur) AS ?scenarioChange)
    }
    GROUP BY ?invId
  }

  # Rebalancing Action per‑investor aggregation
  {
    SELECT ?invId (AVG(xsd:decimal(?rebalanceGap)) AS ?avgRebalancingGap)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:investorId ?invId ;
          wm:targetAllocationPct ?tgt ;
          wm:currentAllocationPct ?cur2 .
      BIND(xsd:decimal(?tgt) - xsd:decimal(?cur2) AS ?rebalanceGap)
    }
    GROUP BY ?invId
  }

  # Portfolio Health per‑investor aggregation
  {
    SELECT ?invId (AVG(xsd:decimal(?riskScore)) AS ?avgHealthRisk)
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:investorId ?invId ;
          wm:riskScore ?riskScore .
    }
    GROUP BY ?invId
  }

  # Investment Goal per‑investor aggregation
  {
    SELECT ?invId (AVG(xsd:decimal(?progressPct)) AS ?avgGoalMatch)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?invId ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?invId
  }
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?sectorFocus
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:investorId ?investorId . }
  OPTIONAL { ?investor wm:investorName ?investorName . }
  OPTIONAL { ?investor wm:sectorFocus ?sectorFocus . }
  FILTER( !BOUND(?sectorFocus) || STRLEN(STR(?sectorFocus)) = 0 )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(?avgGoalShortfall) AS ?avg_goal_shortfall)
       (AVG(?maxAllocationPct) AS ?avg_allocation_concentration)
       (AVG(?liquidityScore) AS ?avg_liquidity_score)
       (AVG(?divScore) AS ?avg_diversification_score)
WHERE {
  ?inv a wm:Investor ;
       wm:riskTolerance ?riskTolerance .

  {
    SELECT ?inv (AVG(xsd:decimal(?shortfall)) AS ?avgGoalShortfall)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv ;
            wm:shortfall ?shortfall .
    }
    GROUP BY ?inv
  }

  {
    SELECT ?inv (MAX(xsd:decimal(?allocationPct)) AS ?maxAllocationPct)
    WHERE {
      ?alloc a wm:SectorAllocation ;
             wm:allocationOfInvestor ?inv ;
             wm:allocationPct ?allocationPct .
    }
    GROUP BY ?inv
  }

  {
    SELECT ?inv ?liquidityScore ?divScore
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:healthOfInvestor ?inv ;
          wm:liquidityScore ?liquidityScore ;
          wm:diversificationScore ?divScore .
    }
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName ?avg_progress ?riskScore ?liquidityScore
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avg_progress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
    HAVING (AVG(xsd:decimal(?progressPct)) < 20)
  }

  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  ?ph a wm:PortfolioHealth ;
       wm:investorId ?investorId ;
       wm:riskScore ?riskScore ;
       wm:liquidityScore ?liquidityScore .

  FILTER (xsd:decimal(?riskScore) < 30 && xsd:decimal(?liquidityScore) < 30)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (SUM(xsd:decimal(COALESCE(?inflow, 0))) AS ?total_inflow)
       (SUM(xsd:decimal(COALESCE(?outflow, 0))) AS ?total_outflow)
       (SUM(xsd:decimal(COALESCE(?shortfall, 0))) AS ?total_shortfall)
       (SUM(xsd:decimal(COALESCE(?dividends, 0))) AS ?total_dividends)
       (SUM(xsd:decimal(COALESCE(?taxesPaid, 0))) AS ?total_taxes_paid)
WHERE {
  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:riskTolerance ?rt . }
  BIND(COALESCE(STR(?rt), "NULL") AS ?riskTolerance) .

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(IF(LCASE(STR(?type)) = "inflow", ?amt, 0))) AS ?inflow)
                 (SUM(xsd:decimal(IF(LCASE(STR(?type)) = "outflow", ?amt, 0))) AS ?outflow)
    WHERE {
      ?cf a wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?inv .
      ?cf wm:amount ?amt .
      ?cf wm:type ?type .
      FILTER(LCASE(STR(?type)) = "inflow" || LCASE(STR(?type)) = "outflow")
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?sf)) AS ?shortfall)
    WHERE {
      ?goal a wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?inv .
      ?goal wm:shortfall ?sf .
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?div)) AS ?dividends)
    WHERE {
      ?ph a wm:PortfolioHolding .
      ?ph wm:heldByInvestor ?inv .
      ?ph wm:dividends ?div .
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?tax)) AS ?taxesPaid)
    WHERE {
      ?ph a wm:PortfolioHolding .
      ?ph wm:heldByInvestor ?inv .
      ?ph wm:taxesPaid ?tax .
    }
    GROUP BY ?inv
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorName ?investorId
WHERE {
  ?investor a wm:Investor ;
            wm:investorName ?investorName ;
            wm:investorId ?investorId ;
            wm:riskTolerance ?riskTol .
  FILTER(LCASE(STR(?riskTol)) = "conservative") .

  ?holding a wm:PortfolioHolding ;
           wm:heldByInvestor ?investor ;
           wm:hasInvestmentType ?invType .

  ?invType a wm:InvestmentType ;
           rdfs:label ?invTypeLabel .
  FILTER(LCASE(STR(?invTypeLabel)) = "hedge fund") .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName (AVG(xsd:decimal(?progressPct)) AS ?avgProgressPct)
WHERE {
  ?goal a wm:InvestmentGoal ;
        wm:progressPct ?progressPct ;
        wm:belongsToInvestor ?investor .
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }
}
GROUP BY ?investorId ?investorName
HAVING (AVG(xsd:decimal(?progressPct)) < 25)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?holding ?holdingId ?investmentName WHERE {
  ?holding rdf:type wm:PortfolioHolding .
  OPTIONAL { ?holding wm:holdingId ?holdingId . }
  OPTIONAL { ?holding wm:investmentName ?investmentName . }

  FILTER NOT EXISTS { ?holding wm:investmentType ?invType . }
  FILTER NOT EXISTS { ?holding wm:sector ?sec . }
  FILTER NOT EXISTS { ?holding wm:segment ?seg . }
  FILTER NOT EXISTS { ?holding wm:category ?cat . }

  FILTER NOT EXISTS { ?holding wm:hasInvestmentType ?invTypeObj . }
  FILTER NOT EXISTS { ?holding wm:hasSector ?secObj . }
  FILTER NOT EXISTS { ?holding wm:hasSegment ?segObj . }
  FILTER NOT EXISTS { ?holding wm:hasCategory ?catObj . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?time_horizon
       (AVG(?totalGain) AS ?avg_holding_gain)
       (AVG(?avgRisk) AS ?avg_health_risk)
       (AVG(?avgDiv) AS ?avg_diversification)
WHERE {
  # Base investor with time horizon
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:timeHorizon ?timeHorizonRaw . }
  BIND(COALESCE(STR(?timeHorizonRaw), "NULL") AS ?time_horizon)

  # Holding gain per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?totalGain)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:currentValue ?cv ;
               wm:cost ?c .
      BIND(xsd:decimal(?cv) - xsd:decimal(?c) AS ?gain)
    }
    GROUP BY ?investorId
  }

  # Health scores per investor
  {
    SELECT ?investorId (AVG(xsd:decimal(?riskScore)) AS ?avgRisk)
                     (AVG(xsd:decimal(?divScore)) AS ?avgDiv)
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:investorId ?investorId ;
          wm:riskScore ?riskScore ;
          wm:diversificationScore ?divScore .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?time_horizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?time_horizon
       (SUM(?cashFlowSum) AS ?cash_flow_total)
       (AVG(?scenarioChangeAvg) AS ?scenario_change_avg)
       (AVG(?allocationConcentrationAvg) AS ?allocation_concentration_avg)
       (SUM(?sectorInvestmentSum) AS ?sector_investment_total)
WHERE {
  # Base Investor
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:timeHorizon ?time_horizon_raw . }
  BIND(COALESCE(STR(?time_horizon_raw), "NULL") AS ?time_horizon)

  # CashFlow per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowSum)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?amount .
    }
    GROUP BY ?investorId
  }

  # ScenarioRebalancing per investor
  {
    SELECT ?investorId (AVG(xsd:decimal(?change)) AS ?scenarioChangeAvg)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?investorId ;
          wm:newAllocationPct ?new ;
          wm:currentAllocationPct ?cur .
      BIND(xsd:decimal(?new) - xsd:decimal(?cur) AS ?change)
    }
    GROUP BY ?investorId
  }

  # SectorAllocation per investor
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?allocationPct)) AS ?allocationConcentrationAvg)
           (SUM(xsd:decimal(?totalInvestment)) AS ?sectorInvestmentSum)
    WHERE {
      ?sa a wm:SectorAllocation ;
          wm:investorId ?investorId ;
          wm:allocationPct ?allocationPct ;
          wm:totalInvestment ?totalInvestment .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?time_horizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sector ?avg_returns ?total_investment WHERE {
  {
    SELECT ?sector (AVG(xsd:decimal(?returnsPct)) AS ?avg_returns) WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:sector ?sector ;
          wm:returnsPct ?returnsPct .
    }
    GROUP BY ?sector
  }
  {
    SELECT ?sector (SUM(xsd:decimal(?totalInvestment)) AS ?total_investment) WHERE {
      ?sa a wm:SectorAllocation ;
          wm:sector ?sector ;
          wm:totalInvestment ?totalInvestment .
    }
    GROUP BY ?sector
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?quantitative_burden_score
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  {
    SELECT ?investorId (SUM(xsd:decimal(?shortfall)) AS ?total_shortfall)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:shortfall ?shortfall ;
            wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?total_holding_gain)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:currentValue ?cv ;
               wm:cost ?cost .
      BIND (xsd:decimal(?cv) - xsd:decimal(?cost) AS ?gain)
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?net_cash_flow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?amount .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?riskScore)) AS ?total_risk_score)
    WHERE {
      ?inv2 a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasPortfolioHealth ?ph .
      ?ph wm:riskPressureScore ?riskScore .
    }
    GROUP BY ?investorId
  }

  BIND ( ?total_shortfall - ?total_holding_gain - ?net_cash_flow + ?total_risk_score AS ?quantitative_burden_score )
}
ORDER BY DESC(?quantitative_burden_score) ?investorId
LIMIT 10

