PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (SUM(?cashFlowTotal) AS ?cash_flow_total)
       (AVG(?scenarioChangeAvg) AS ?scenario_change_avg)
       (AVG(?allocationConcentrationAvg) AS ?allocation_concentration_avg)
       (SUM(?sectorInvestmentTotal) AS ?sector_investment_total)
WHERE {
  ?inv a wm:Investor ;
       wm:riskTolerance ?riskTolerance .

  {
    SELECT ?inv (SUM(xsd:decimal(?amount)) AS ?cashFlowTotal)
    WHERE {
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:amount ?amount .
    }
    GROUP BY ?inv
  }

  {
    SELECT ?inv (AVG(xsd:decimal(?change)) AS ?scenarioChangeAvg)
    WHERE {
      ?inv wm:hasScenarioRebalancing ?sr .
      ?sr wm:newAllocationPct ?new .
      ?sr wm:currentAllocationPct ?cur .
      BIND (xsd:decimal(?new) - xsd:decimal(?cur) AS ?change)
    }
    GROUP BY ?inv
  }

  {
    SELECT ?inv (AVG(xsd:decimal(?allocationPct)) AS ?allocationConcentrationAvg)
           (SUM(xsd:decimal(?totalInvestment)) AS ?sectorInvestmentTotal)
    WHERE {
      ?inv wm:hasSectorAllocation ?sa .
      ?sa wm:allocationPct ?allocationPct .
      ?sa wm:totalInvestment ?totalInvestment .
    }
    GROUP BY ?inv
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
