PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }
  FILTER EXISTS { ?investor wm:hasPortfolioHealth ?ph . }
  FILTER EXISTS { ?investor wm:hasHolding ?phold . }
  FILTER NOT EXISTS { ?investor wm:hasRiskTolerance ?rt . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sector (COUNT(DISTINCT ?inv) AS ?distinct_investor_count)
WHERE {
  {
    SELECT DISTINCT ?inv ?sector WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:heldByInvestor ?inv ;
          wm:returnsPct ?returnsPct .
      FILTER(xsd:decimal(?returnsPct) < 0) .

      OPTIONAL {
        ?ph wm:hasSector ?sectorNode .
        OPTIONAL { ?sectorNode rdfs:label ?sectorLabelRaw . }
      }
      BIND(COALESCE(STR(?sectorLabelRaw), "NULL") AS ?sector)

      ?phHealth a wm:PortfolioHealth ;
                wm:healthOfInvestor ?inv ;
                wm:riskScore ?riskScore .
      FILTER(xsd:decimal(?riskScore) > 70) .
    }
  }
}
GROUP BY ?sector

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  ?ph a wm:PortfolioHealth ;
       wm:investorId ?investorId ;
       wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 70)

  FILTER EXISTS {
    ?alloc a wm:SectorAllocation ;
           wm:investorId ?investorId ;
           wm:allocationPct ?allocationPct .
    FILTER(xsd:decimal(?allocationPct) > 30)
  }

  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avg_progress_pct)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (COUNT(?holdingId) AS ?negative_holding_count)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:returnsPct ?returnsPct ;
               wm:holdingId ?holdingId .
      FILTER(xsd:decimal(?returnsPct) < 0)
    }
    GROUP BY ?investorId
  }

  FILTER(?avg_progress_pct < 30)
  FILTER(?negative_holding_count > 0)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investor ?investorId ?investorName WHERE {
  VALUES ?investorClass { wm:Investor kg:Investor }
  ?investor a ?investorClass .

  OPTIONAL { ?investor wm:investorId ?investorId . }
  OPTIONAL { ?investor wm:investorName ?investorName . }

  FILTER NOT EXISTS { ?investor wm:investmentGoal ?_ . }
  FILTER NOT EXISTS { ?investor wm:riskTolerance ?_ . }
  FILTER NOT EXISTS { ?investor wm:timeHorizon ?_ . }
  FILTER NOT EXISTS { ?investor wm:sectorFocus ?_ . }
  FILTER NOT EXISTS { ?investor wm:segment ?_ . }
  FILTER NOT EXISTS { ?investor wm:category ?_ . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?time_horizon ?goal_context (COUNT(DISTINCT ?investorId) AS ?investor_count)
WHERE {
  {
    SELECT DISTINCT ?investorId ?time_horizon ?goal_context
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:shortfall ?shortfall ;
            wm:investmentGoal ?goal_context ;
            wm:belongsToInvestor ?inv .
      FILTER(xsd:decimal(?shortfall) > 0) .

      ?inv a wm:Investor ;
           wm:investorId ?investorId .

      OPTIONAL { ?inv wm:timeHorizon ?time_horizon_raw . }
      BIND(COALESCE(STR(?time_horizon_raw), "NULL") AS ?time_horizon) .
    }
  }
}
GROUP BY ?time_horizon ?goal_context

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment
       (SUM(?raSum) AS ?total_rebalancing_amount)
       (SUM(?cfSum) AS ?total_cash_flow_amount)
       (SUM(?raCount) AS ?total_transaction_count)
WHERE {
  # Investor with segment
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:segment ?segmentRaw . }
  BIND(COALESCE(STR(?segmentRaw), "NULL") AS ?segment)

  # Pre‑aggregate RebalancingAction per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?raAmount)) AS ?raSum) (COUNT(?rebalanceId) AS ?raCount)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:investorId ?investorId ;
          wm:amount ?raAmount ;
          wm:rebalanceId ?rebalanceId .
    }
    GROUP BY ?investorId
  }

  # Pre‑aggregate CashFlow per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?cfSum)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?cfAmount .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?segment

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (AVG(?scenarioChange) AS ?avg_scenario_change)
       (AVG(?rebalanceGap) AS ?avg_rebalancing_gap)
       (AVG(?rebalanceAmount) AS ?avg_rebalancing_amount)
WHERE {
  ?inv a wm:Investor ;
       wm:category ?category .

  {
    SELECT ?inv (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?scenarioChange)
    WHERE {
      ?inv wm:hasScenarioRebalancing ?sr .
      ?sr a wm:ScenarioRebalancing ;
          wm:newAllocationPct ?newAlloc ;
          wm:currentAllocationPct ?currAlloc .
    }
    GROUP BY ?inv
  }

  {
    SELECT ?inv (SUM(xsd:decimal(?target) - xsd:decimal(?curr)) AS ?rebalanceGap)
                 (SUM(xsd:decimal(?amount)) AS ?rebalanceAmount)
    WHERE {
      ?inv wm:hasRebalancingAction ?ra .
      ?ra a wm:RebalancingAction ;
          wm:targetAllocationPct ?target ;
          wm:currentAllocationPct ?curr ;
          wm:amount ?amount .
    }
    GROUP BY ?inv
  }
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category 
       (SUM(xsd:decimal(?cashFlowSum)) AS ?cash_flow_net_amount) 
       (AVG(xsd:decimal(?goalProgressAvg)) AS ?goal_progress) 
       (SUM(xsd:decimal(?shortfallSum)) AS ?shortfall)
WHERE {
  {
    SELECT ?investorId ?category 
           (SUM(xsd:decimal(?amount)) AS ?cashFlowSum) 
           (AVG(xsd:decimal(?progressPct)) AS ?goalProgressAvg) 
           (SUM(xsd:decimal(?shortfall)) AS ?shortfallSum)
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorId ;
                wm:category ?category .
      ?cashFlow rdf:type wm:CashFlow ;
                wm:cashFlowOfInvestor ?investor ;
                wm:amount ?amount .
      ?goal rdf:type wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPct ;
            wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId ?category
  }
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (SUM(?cashSum) AS ?cash_flow_net_amount)
       (AVG(?scenarioAvgDiff) AS ?scenario_change)
       (SUM(?scenarioCount) AS ?scenario_count)
WHERE {
  # Investor base
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:riskTolerance ?riskToleranceRaw .
  BIND(COALESCE(STR(?riskToleranceRaw), "NULL") AS ?riskTolerance)

  # CashFlow aggregation per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashSum)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?amount .
    }
    GROUP BY ?investorId
  }

  # ScenarioRebalancing aggregation per investor
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?diff)) AS ?scenarioAvgDiff)
           (COUNT(?scenarioRebalanceId) AS ?scenarioCount)
    WHERE {
      ?sc a wm:ScenarioRebalancing ;
          wm:investorId ?investorId ;
          wm:newAllocationPct ?newPct ;
          wm:currentAllocationPct ?currPct ;
          wm:scenarioRebalanceId ?scenarioRebalanceId .
      BIND(xsd:decimal(?newPct) - xsd:decimal(?currPct) AS ?diff)
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment
       (AVG(?riskScore_perInv) AS ?avg_riskScore)
       (AVG(?liquidityScore_perInv) AS ?avg_liquidityScore)
       (AVG(?diversificationScore_perInv) AS ?avg_diversificationScore)
       (AVG(?goalMatchPct_perInv) AS ?avg_goalMatchPct)
WHERE {
  {
    SELECT ?investorId
           (AVG(xsd:decimal(?riskScore)) AS ?riskScore_perInv)
           (AVG(xsd:decimal(?liquidityScore)) AS ?liquidityScore_perInv)
           (AVG(xsd:decimal(?diversificationScore)) AS ?diversificationScore_perInv)
           (AVG(xsd:decimal(?goalMatchPct)) AS ?goalMatchPct_perInv)
    WHERE {
      ?ph a wm:PortfolioHealth .
      ?ph wm:investorId ?investorId .
      OPTIONAL { ?ph wm:riskScore ?riskScore . }
      OPTIONAL { ?ph wm:liquidityScore ?liquidityScore . }
      OPTIONAL { ?ph wm:diversificationScore ?diversificationScore . }
      OPTIONAL { ?ph wm:goalMatchPct ?goalMatchPct . }
    }
    GROUP BY ?investorId
  }
  ?inv a wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:segment ?segmentRaw . }
  BIND(COALESCE(?segmentRaw, "NULL") AS ?segment)
}
GROUP BY ?segment

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (SUM(xsd:integer(COALESCE(?holdingsPerInvestor, 0))) AS ?holdings_count)
       (COUNT(DISTINCT ?investorId) AS ?distinct_investors_count)
WHERE {
  ?inv rdf:type wm:Investor .
  OPTIONAL { ?inv wm:investorId ?investorId . }
  OPTIONAL { ?inv wm:category ?catRaw . }
  BIND(COALESCE(STR(?catRaw), "NULL") AS ?category)

  OPTIONAL {
    SELECT ?investorId (COUNT(?holding) AS ?holdingsPerInvestor)
    WHERE {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?invHolding .
      ?invHolding wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?profileSegment WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }
  OPTIONAL { ?inv wm:segment ?profileSegment . }

  FILTER NOT EXISTS {
    ?hold rdf:type wm:PortfolioHolding .
    ?hold wm:heldByInvestor ?inv .
    ?hold wm:segment ?profileSegment .
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv rdf:type wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:hasScenarioRebalancing ?sr ;
       wm:hasInvestmentGoal ?goal .

  ?sr rdf:type wm:ScenarioRebalancing ;
      wm:scenario ?scenario .
  FILTER(LCASE(STR(?scenario)) = "bear market")

  ?goal rdf:type wm:InvestmentGoal ;
        wm:progressPct ?progressPct .
  FILTER(xsd:decimal(?progressPct) < 25)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?riskScore
WHERE {
  {
    SELECT DISTINCT ?investorId
    WHERE {
      ?inv rdf:type wm:Investor .
      ?inv wm:investorId ?investorId .
      ?holding rdf:type wm:PortfolioHolding ;
               wm:heldByInvestor ?inv ;
               wm:returnsPct ?ret .
      FILTER(xsd:decimal(?ret) < 0)
    }
  }
  ?inv rdf:type wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }
  ?inv wm:hasPortfolioHealth ?ph .
  ?ph wm:riskScore ?riskScoreRaw .
  BIND(xsd:decimal(?riskScoreRaw) AS ?riskScore)
}
ORDER BY DESC(?riskScore) ?investorId
LIMIT 5

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv rdf:type wm:Investor .
  OPTIONAL { ?inv wm:investorId ?investorId . }
  OPTIONAL { ?inv wm:investorName ?investorName . }

  # Profile context properties
  OPTIONAL { ?inv wm:hasSegment ?invSeg . }
  OPTIONAL { ?inv wm:hasRiskTolerance ?invRisk . }
  OPTIONAL { ?inv wm:hasInvestmentGoal ?invGoal . }
  OPTIONAL { ?inv wm:hasTimeHorizon ?invTime . }
  OPTIONAL { ?inv wm:hasSectorAllocation ?invSectorAlloc . }

  FILTER (
    (!BOUND(?invSeg)) ||
    (!BOUND(?invRisk)) ||
    (!BOUND(?invGoal)) ||
    (!BOUND(?invTime)) ||
    (!BOUND(?invSectorAlloc)) ||
    NOT EXISTS {
      ?holding wm:heldByInvestor ?inv .
      ?holding wm:hasSegment ?holdSeg .
      ?inv wm:hasSegment ?holdSeg .
    }
  )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (SUM(COALESCE(?cashInflow, 0)) AS ?cash_inflow)
       (SUM(COALESCE(?cashOutflow, 0)) AS ?cash_outflow)
       (SUM(COALESCE(?goalShortfall, 0)) AS ?goal_shortfall)
       (SUM(COALESCE(?totalDividends, 0)) AS ?total_dividends)
       (SUM(COALESCE(?totalTaxesPaid, 0)) AS ?total_taxes_paid)
WHERE {
  # Base Investor
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .

  # Category (preserve null groups)
  OPTIONAL { ?investor wm:category ?catRaw . }
  BIND(COALESCE(STR(?catRaw), "NULL") AS ?category)

  # Cash inflow per investor (positive amounts)
  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?amtPos)) AS ?cashInflow) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:investorId ?investorId .
      ?cf wm:amount ?amtPos .
      FILTER(xsd:decimal(?amtPos) > 0)
    } GROUP BY ?investorId
  }

  # Cash outflow per investor (negative amounts, summed as positive)
  OPTIONAL {
    SELECT ?investorId (SUM(-xsd:decimal(?amtNeg)) AS ?cashOutflow) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:investorId ?investorId .
      ?cf wm:amount ?amtNeg .
      FILTER(xsd:decimal(?amtNeg) < 0)
    } GROUP BY ?investorId
  }

  # Goal shortfall per investor
  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?sf)) AS ?goalShortfall) WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:investorId ?investorId .
      ?goal wm:shortfall ?sf .
    } GROUP BY ?investorId
  }

  # Dividends per investor
  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?div)) AS ?totalDividends) WHERE {
      ?ph rdf:type wm:PortfolioHolding .
      ?ph wm:investorId ?investorId .
      ?ph wm:dividends ?div .
    } GROUP BY ?investorId
  }

  # Taxes paid per investor
  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?tax)) AS ?totalTaxesPaid) WHERE {
      ?ph rdf:type wm:PortfolioHolding .
      ?ph wm:investorId ?investorId .
      ?ph wm:taxesPaid ?tax .
    } GROUP BY ?investorId
  }
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskScore
       (AVG(?avgGoalShortfall) AS ?avg_goal_shortfall)
       (AVG(?sumHoldingValue) AS ?avg_holding_value)
       (AVG(?maxAllocationPct) AS ?avg_allocation_concentration)
       (AVG(?avgLiquidityScore) AS ?avg_liquidity)
       (AVG(?avgDiversificationScore) AS ?avg_diversification)
WHERE {
  {
    SELECT ?investorId ?riskScore
           (AVG(xsd:decimal(?shortfall)) AS ?avgGoalShortfall)
           (SUM(xsd:decimal(?holdingValue)) AS ?sumHoldingValue)
           (MAX(xsd:decimal(?allocationPct)) AS ?maxAllocationPct)
           (AVG(xsd:decimal(?liquidityScore)) AS ?avgLiquidityScore)
           (AVG(xsd:decimal(?diversificationScore)) AS ?avgDiversificationScore)
    WHERE {
      ?investor a wm:Investor ;
                wm:investorId ?investorId .

      ?rebalance a wm:RebalancingAction ;
                 wm:investorId ?investorId .

      ?goal a wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:shortfall ?shortfall .

      ?holding a wm:PortfolioHolding ;
               wm:investorId ?investorId ;
               wm:currentValue ?holdingValue .

      ?alloc a wm:SectorAllocation ;
             wm:investorId ?investorId ;
             wm:allocationPct ?allocationPct .

      ?health a wm:PortfolioHealth ;
              wm:investorId ?investorId ;
              wm:riskScore ?riskScore ;
              wm:liquidityScore ?liquidityScore ;
              wm:diversificationScore ?diversificationScore .
    }
    GROUP BY ?investorId ?riskScore
  }
}
GROUP BY ?riskScore
ORDER BY ?riskScore

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId
       ?total_cash_flow
       ?total_rebalancing_amount
       ?avg_scenario_change
       ?avg_risk_score
       ?avg_goal_match_pct
WHERE {
  {
    SELECT ?invIdCash (SUM(xsd:decimal(?amount)) AS ?total_cash_flow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?invIdCash ;
          wm:amount ?amount .
    }
    GROUP BY ?invIdCash
  }
  {
    SELECT ?invIdReb (SUM(xsd:decimal(?raAmount)) AS ?total_rebalancing_amount)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:investorId ?invIdReb ;
          wm:amount ?raAmount .
    }
    GROUP BY ?invIdReb
  }
  {
    SELECT ?invIdScen (AVG(xsd:decimal(?change)) AS ?avg_scenario_change)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?invIdScen ;
          wm:newAllocationPct ?new ;
          wm:currentAllocationPct ?cur .
      BIND(xsd:decimal(?new) - xsd:decimal(?cur) AS ?change)
    }
    GROUP BY ?invIdScen
  }
  {
    SELECT ?invIdHealth (AVG(xsd:decimal(?riskScore)) AS ?avg_risk_score)
                         (AVG(xsd:decimal(?goalMatch)) AS ?avg_goal_match_pct)
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:investorId ?invIdHealth ;
          wm:riskScore ?riskScore ;
          wm:goalMatchPct ?goalMatch .
    }
    GROUP BY ?invIdHealth
  }
  {
    SELECT DISTINCT ?invIdGoal
    WHERE {
      ?ig a wm:InvestmentGoal ;
          wm:investorId ?invIdGoal .
    }
  }
  # Enforce inner join across all sub‑queries
  FILTER ( ?invIdCash = ?invIdReb &&
           ?invIdCash = ?invIdScen &&
           ?invIdCash = ?invIdHealth &&
           ?invIdCash = ?invIdGoal )
  BIND(?invIdCash AS ?investorId)
}
